	function openDedicatedAccountPage(panelId, bodyClass)
	{
		closeMainLandingBeforeProfileSuite();
		resetWorkspaceForStandalonePage();
		if (authModal) {
			authModal.classList.remove("open", "profile-page-mode");
			authModal.setAttribute("aria-hidden", "true");
		}
		hideAllAuthScreens();
		document.body.classList.add(
			"sidebar-list-collapsed",
			"realjeju-document-page-open",
			"realjeju-account-page-open",
			bodyClass
		);
		// 계정 화면은 진입 직전 서비스의 상단 선택과 오른쪽 메뉴 구성을 그대로 유지한다.
		REALJEJU_DEDICATED_ACCOUNT_BODY_CLASSES.forEach((className) => {
			if (className !== bodyClass) document.body.classList.remove(className);
		});
		hideDedicatedAccountPanels(panelId);
		if (typeof state !== "undefined" && state) state.isListOpen = false;
		if (sidebar) sidebar.classList.remove("expanded");
		const panel = document.getElementById(panelId);
		if (!panel) return;
		panel.setAttribute("aria-hidden", "false");
		panel.style.display = panelId === "mySuitePanel" ? "block" : "";
		panel.style.zIndex = panelId === "mySuitePanel" ? "10040" : "";
		window.scrollTo({ top: 0, left: 0, behavior: "auto" });
		document.querySelectorAll(".topbar-menu-item").forEach((btn) => btn.classList.remove("active"));
		const topbarAccountTrigger = document.querySelector(".global-auth-trigger");
		if (topbarAccountTrigger) topbarAccountTrigger.classList.add("profile-page-active");
		document.body.style.overflow = "";
		if (typeof window.realjejuReleaseStandalonePageTransitionCover === "function") {
			window.realjejuReleaseStandalonePageTransitionCover();
		}
	}

	// 계정 화면 진입 함수는 마이스위트 라우터와 별도 초기화 영역에서 함께 사용한다.
	window.realjejuCloseDedicatedAccountPages = closeDedicatedAccountPages;
	window.realjejuCloseMainLandingBeforeProfileSuite = closeMainLandingBeforeProfileSuite;
	window.realjejuResetWorkspaceForStandalonePage = resetWorkspaceForStandalonePage;
	window.realjejuOpenDedicatedAccountPage = openDedicatedAccountPage;

