	function openBrokerOfficeInfoPageWithOffice(brokerOffice)
	{
		if (!brokerOffice) return;
		window.realjejuCurrentBrokerOffice = {
			...(window.realjejuCurrentBrokerOffice || {}),
			...brokerOffice,
			kakao_url: getBrokerOfficeKakaoUrl(brokerOffice)
		};
		fillBrokerOfficePageInfo(window.realjejuCurrentBrokerOffice);
		openProfileSuitePanel("brokerOfficeInfoPagePanel", "broker-office-info-page-open");
		document.body.style.overflow = "";
	}

	async function openBrokerOfficeInfoFromAccountMenu()
	{
		if (typeof window.realjejuShowStandalonePageTransitionCover === "function") {
			window.realjejuShowStandalonePageTransitionCover();
		}
		closeGlobalAccountDropdown();
		const cachedUser = window.realjejuCurrentAuthUser || currentRealjejuAuthUser || null;
		const cachedProfile = window.realjejuCurrentProfile || null;
		const cachedBrokerOffice = window.realjejuCurrentBrokerOffice || null;
		let openedEarly = false;
		if (cachedUser && cachedUser.id) {
			if (isApprovedBrokerOffice(cachedBrokerOffice)) fillBrokerOfficePageInfo(cachedBrokerOffice);
			else renderBrokerOfficeInfoLoadingPageForAccount();
			openProfileSuitePanel("brokerOfficeInfoPagePanel", "broker-office-info-page-open");
			document.body.style.overflow = "";
			openedEarly = true;
		}
		try {
			const { user, profile, brokerOffice } = await fetchCurrentProfileAndBrokerOffice();
			if (!user) {
				if (typeof window.realjejuReleaseStandalonePageTransitionCover === "function") {
					window.realjejuReleaseStandalonePageTransitionCover();
				}
				if (!openedEarly) openAuthModal();
				return;
			}
			if (!isApprovedBrokerOffice(brokerOffice)) {
				if (!brokerOffice && isApprovedBrokerOffice(cachedBrokerOffice)) {
					openBrokerOfficeInfoPageWithOffice(cachedBrokerOffice);
					return;
				}
				renderBrokerOfficeInfoEmptyPageForAccount(profile, brokerOffice);
				if (!openedEarly) {
					openProfileSuitePanel("brokerOfficeInfoPagePanel", "broker-office-info-page-open");
					document.body.style.overflow = "";
				}
				return;
			}
			openBrokerOfficeInfoPageWithOffice(brokerOffice);
		} catch (err) {
			console.warn("중개사무소 정보 열기 실패:", err);
			if (typeof window.realjejuReleaseStandalonePageTransitionCover === "function") {
				window.realjejuReleaseStandalonePageTransitionCover();
			}
			if (!openedEarly) openAuthErrorModal("중개사무소 정보를 열지 못했습니다.", "중개사무소 정보", null);
			else if (!isApprovedBrokerOffice(cachedBrokerOffice)) renderBrokerOfficeInfoEmptyPageForAccount(cachedProfile, cachedBrokerOffice);
		}
	}

	window.realjejuOpenBrokerOfficeInfoFromAccountMenu = openBrokerOfficeInfoFromAccountMenu;

