		const messageText = String(authErrorMessage && authErrorMessage.textContent || "");
		if (!titleText.includes("비밀번호 재설정") && !messageText.includes("새 비밀번호를 먼저")) return;
		if (authErrorModal.contains(document.activeElement) && document.activeElement && typeof document.activeElement.blur === "function") {
			document.activeElement.blur();
		}
		authErrorModal.classList.remove("open", "confirm-mode");
		authErrorModal.setAttribute("aria-hidden", "true");
		authErrorReturnFocusTarget = null;
		authErrorConfirmAction = null;
		authErrorCancelAction = null;
