	function pushPropertyRegisterBrokerHomeHistory(listingId)
	{
		const page = document.getElementById("propertyRegisterPage");
		if (!page || page.dataset.returnToBrokerHome !== "1" || page.dataset.returnHistoryPushed === "1") return;
		try {
			const currentState = window.history && window.history.state && typeof window.history.state === "object"
				? window.history.state
				: {};
			const url = new URL(window.location.href);
			url.searchParams.delete(typeof DETAIL_QUERY_KEY === "string" ? DETAIL_QUERY_KEY : "id");
			url.searchParams.set("brokerEdit", String(listingId || page.dataset.returnBrokerListingId || "1"));
			window.history.pushState({
				...currentState,
				realjejuBrokerHomeEdit: true,
				realjejuBrokerListingId: String(listingId || page.dataset.returnBrokerListingId || "")
			}, "", `${url.pathname}${url.search}${url.hash}`);
			page.dataset.returnHistoryPushed = "1";
		} catch (error) {}
	}

