	async function reopenMapHomeListingDetail(listingId)
	{
		const id = normalizeItemId(listingId);
		try {
			if (typeof window.realjejuGoHome === "function") {
				const result = window.realjejuGoHome({ resetDetail: false });
				if (result && typeof result.then === "function") await result.catch(() => {});
			}
		} catch (error) {}
		try {
			if (id && typeof window.realjejuRefreshSavedListingInMemory === "function") {
				const refreshResult = window.realjejuRefreshSavedListingInMemory(id, { repaintMap: true });
				if (refreshResult && typeof refreshResult.then === "function") await refreshResult.catch(() => {});
			}
		} catch (error) {}
		restoreMapHomeListPanelForEditReturn();
		if (!id) return;
		let listing = typeof findRealJejuListingById === "function" ? findRealJejuListingById(id) : null;
		if (!listing && typeof resolveDetailDataFromDatabase === "function") {
			listing = await resolveDetailDataFromDatabase({ id }).catch(() => null);
		}
		if (!listing) return;
		try {
			restoreMapHomeListPanelForEditReturn();
			allowDetailOpenFromListClick = true;
			await openDetailPanel(listing, {
				syncUrl: false,
				forceOpen: true,
				overlayPage: false,
				sharedMode: false,
				skipRecentViewTracking: true
			});
			restoreMapHomeListPanelForEditReturn();
			if (typeof updateMapPanelToggleState === "function") updateMapPanelToggleState();
		} catch (error) {
			console.error("부동산 홈 수정 복귀 상세 열기 실패:", error);
		}
	}

