					if (typeof renderRealjejuMySuiteFavoritesContent === "function") renderRealjejuMySuiteFavoritesContent();
					if (typeof setMySuiteFavoriteSelectedId === "function") setMySuiteFavoriteSelectedId(id);
					const favoriteItems = typeof getFavoriteListingItems === "function" ? getFavoriteListingItems(mySuiteFavoriteView) : [];
					const item = (Array.isArray(favoriteItems) ? favoriteItems : []).find((entry) => normalizeItemId(entry && entry.id) === id) || { id };
