	const adminTabScrollTopByContext = new Map();

	function getAdminTabScrollMemoryKey(context, tabKey)
	{
		return `${String(context || "admin")}:${String(tabKey || "")}`;
	}

	function rememberAdminTabScrollTop(context, tabKey)
	{
		const panel = document.getElementById("adminPagePanel");
		if (!panel || !tabKey) return;
		adminTabScrollTopByContext.set(
			getAdminTabScrollMemoryKey(context, tabKey),
			Math.max(0, Number(panel.scrollTop) || 0)
		);
	}

	function restoreAdminTabScrollTop(context, tabKey)
	{
		const panel = document.getElementById("adminPagePanel");
		if (!panel || !tabKey) return;
		const savedTop = Math.max(
			0,
			Number(adminTabScrollTopByContext.get(getAdminTabScrollMemoryKey(context, tabKey))) || 0
		);
		const applySavedTop = () => {
			panel.scrollTop = Math.min(savedTop, Math.max(0, panel.scrollHeight - panel.clientHeight));
		};
		applySavedTop();
		requestAnimationFrame(applySavedTop);
	}

