	function resetAdminNoticeForm()
	{
		const idInput = document.getElementById("adminNoticeIdInput");
		const titleInput = document.getElementById("adminNoticeTitleInput");
		const contentInput = document.getElementById("adminNoticeContentInput");
		const categoryInput = document.getElementById("adminNoticeCategoryInput");
		const pinnedInput = document.getElementById("adminNoticePinnedInput");
		const visibleInput = document.getElementById("adminNoticeVisibleInput");
		const statusEl = document.getElementById("adminNoticeStatus");
		if (idInput) idInput.value = "";
		if (titleInput) titleInput.value = "";
		if (contentInput) contentInput.value = "";
		if (categoryInput) {
			categoryInput.value = "공지";
			categoryInput.dispatchEvent(new Event("change", { bubbles: true }));
		}
		if (pinnedInput) pinnedInput.checked = false;
		if (visibleInput) visibleInput.checked = true;
		if (statusEl) statusEl.textContent = "";
	}

	function fillAdminNoticeForm(row)
	{
		const idInput = document.getElementById("adminNoticeIdInput");
		const titleInput = document.getElementById("adminNoticeTitleInput");
		const contentInput = document.getElementById("adminNoticeContentInput");
		const categoryInput = document.getElementById("adminNoticeCategoryInput");
		const pinnedInput = document.getElementById("adminNoticePinnedInput");
		const visibleInput = document.getElementById("adminNoticeVisibleInput");
		if (idInput) idInput.value = row.id || "";
		if (titleInput) titleInput.value = row.title || "";
		if (contentInput) contentInput.value = row.content || "";
		if (categoryInput) {
			categoryInput.value = row.category || "공지";
			categoryInput.dispatchEvent(new Event("change", { bubbles: true }));
		}
		if (pinnedInput) pinnedInput.checked = !!row.is_pinned;
		if (visibleInput) visibleInput.checked = row.is_visible !== false;
		document.getElementById("adminNoticeForm")?.scrollIntoView({ block: "center", behavior: "smooth" });
	}

	function renderAdminNoticeRows(rows)
	{
		const listEl = document.getElementById("adminNoticeList");
		const countEl = document.getElementById("adminNoticeListCount");
		if (!listEl) return;
		if (countEl) countEl.textContent = `${Array.isArray(rows) ? rows.length : 0}건`;
		if (!rows.length) {
			listEl.innerHTML = '<div class="admin-empty">등록된 공지사항이 없습니다.</div>';
			return;
		}
		window.realjejuAdminNoticeRowsById = new Map(rows.map((row) => [String(row.id || ""), row]));
		listEl.innerHTML = rows.map((row) => {
			const id = escapeAdminHtml(row.id || "");
			const visible = row.is_visible !== false;
			return `
				<div class="admin-notice-row" data-notice-id="${id}">
					<div>
						<div class="admin-notice-row-title">
							${row.is_pinned ? '<span class="admin-notice-chip pinned">고정</span>' : ""}
							<span>${escapeAdminHtml(row.title || "제목 없음")}</span>
						</div>
						<div class="admin-notice-row-meta">
							<span>${escapeAdminHtml(row.category || "공지")}</span>
							<span>${escapeAdminHtml(formatAdminNoticeDate(row.created_at))}</span>
							<span class="admin-notice-chip ${visible ? "visible" : "hidden"}">${visible ? "공개" : "비공개"}</span>
						</div>
					</div>
					<div class="admin-notice-row-actions">
						<button type="button" class="admin-status-btn" data-admin-notice-edit="${id}">수정</button>
						<button type="button" class="admin-status-btn pending" data-admin-notice-toggle="${id}">${visible ? "비공개" : "공개"}</button>
						<button type="button" class="admin-status-btn reject" data-admin-notice-delete="${id}">삭제</button>
					</div>
				</div>
			`;
		}).join("");
	}

	async function loadAdminNotices()
	{
		const listEl = document.getElementById("adminNoticeList");
		const countEl = document.getElementById("adminNoticeListCount");
		if (!listEl) return;
		if (countEl) countEl.textContent = "0건";
		if (!isAdminUser(currentRealjejuAuthUser)) {
			listEl.innerHTML = '<div class="admin-empty">관리자 계정으로 로그인하세요.</div>';
			return;
		}
		const client = getRealjejuSupabaseClient();
		if (!client) {
			listEl.innerHTML = '<div class="admin-empty">Supabase 연결 설정을 확인하세요.</div>';
			return;
		}
		listEl.innerHTML = '<div class="admin-empty">공지사항을 불러오는 중입니다.</div>';
		try {
			await purgeAdminExpiredTrashIfNeeded(client);
			const { data, error } = await client
				.from("notices")
				.select("id, title, content, category, is_pinned, is_visible, created_by, created_at, updated_at, deleted_at")
				.is("deleted_at", null)
				.order("is_pinned", { ascending: false })
				.order("created_at", { ascending: false });
			if (error) throw error;
			renderAdminNoticeRows(Array.isArray(data) ? data : []);
		} catch (err) {
			console.error("관리자 공지사항 조회 실패:", err);
			listEl.innerHTML = `<div class="admin-empty">공지사항을 불러오지 못했습니다. ${escapeAdminHtml(getNoticeSchemaHelp())}</div>`;
		}
	}

	async function saveAdminNotice()
	{
		const statusEl = document.getElementById("adminNoticeStatus");
		const values = getAdminNoticeFormValues();
		if (!values.title || !values.content) {
			if (statusEl) statusEl.textContent = "제목과 내용을 입력하세요.";
			return;
		}
		const user = currentRealjejuAuthUser;
		const client = getRealjejuSupabaseClient();
		if (!isAdminUser(user) || !client) {
			if (statusEl) statusEl.textContent = "관리자 로그인과 Supabase 연결을 확인하세요.";
			return;
		}
		if (statusEl) statusEl.textContent = "저장 중입니다.";
		try {
			const now = new Date().toISOString();
			const payload = {
				title: values.title,
				content: values.content,
				category: values.category || "공지",
				is_pinned: values.isPinned,
				is_visible: values.isVisible,
				updated_at: now
			};
			const result = values.id
				? await client.from("notices").update(payload).eq("id", values.id)
				: await client.from("notices").insert({ ...payload, created_by: user.id, created_at: now });
			if (result.error) throw result.error;
			if (statusEl) statusEl.textContent = "저장했습니다.";
			resetAdminNoticeForm();
			await loadAdminNotices();
			if (typeof window.refreshPublicNotices === "function") await window.refreshPublicNotices();
		} catch (err) {
			console.error("공지사항 저장 실패:", err);
			if (statusEl) statusEl.textContent = `저장 실패: ${getNoticeSchemaHelp()}`;
		}
	}

	async function toggleAdminNoticeVisibility(id)
	{
		const row = window.realjejuAdminNoticeRowsById?.get(String(id || ""));
		if (!row) return;
		const client = getRealjejuSupabaseClient();
		if (!client || !isAdminUser(currentRealjejuAuthUser)) return;
		const { error } = await client
			.from("notices")
			.update({ is_visible: row.is_visible === false, updated_at: new Date().toISOString() })
			.eq("id", row.id);
		if (error) {
			openAuthErrorModal("공지 공개 상태 변경에 실패했습니다.", "공지사항 관리", null);
			return;
		}
		await loadAdminNotices();
		if (typeof window.refreshPublicNotices === "function") await window.refreshPublicNotices();
	}

	async function deleteAdminNotice(id)
	{
		const client = getRealjejuSupabaseClient();
		if (!client || !isAdminUser(currentRealjejuAuthUser)) return;
		const { error } = await client
			.from("notices")
			.update({ deleted_at: new Date().toISOString(), is_visible: false, updated_at: new Date().toISOString() })
			.eq("id", id);
		if (error) {
			openAuthErrorModal("공지 삭제에 실패했습니다.", "공지사항 관리", null);
			return;
		}
		resetAdminNoticeForm();
		await loadAdminNotices();
		if (typeof window.refreshPublicNotices === "function") await window.refreshPublicNotices();
	}

	async function fetchAdminInquiryRows(client)
	{
		const { data, error } = await client.rpc("get_admin_support_inquiries");
		if (error) throw error;
		return Array.isArray(data) ? data : [];
	}

	function isAdminInquiryDeleted(row)
	{
		const status = String(row && row.status || "").trim().toLowerCase();
		return ["deleted", "trash", "withdrawn", "삭제", "휴지통"].includes(status) || !!(row && row.deleted_at);
	}

	function isAdminInquiryAnswered(row)
	{
		if (isAdminInquiryDeleted(row)) return false;
		const status = String(row && row.status || "").trim().toLowerCase();
		return ["answered", "replied", "completed", "done", "답변완료", "완료"].includes(status) || !!String(row && row.admin_reply || "").trim();
	}

	function getAdminInquiryFilteredRows(rows)
	{
		const list = Array.isArray(rows) ? rows : [];
		if (adminInquiryView === "pending") return list.filter((row) => !isAdminInquiryAnswered(row) && !isAdminInquiryDeleted(row));
		if (adminInquiryView === "answered") return list.filter(isAdminInquiryAnswered);
		if (adminInquiryView === "deleted") return list.filter(isAdminInquiryDeleted);
		return list.filter((row) => !isAdminInquiryAnswered(row) && !isAdminInquiryDeleted(row));
	}

	function updateAdminInquiryFilterCounts(rows)
	{
		const list = Array.isArray(rows) ? rows : [];
		const setText = (id, value) => {
			const el = document.getElementById(id);
			if (el) el.textContent = String(value);
		};
		setText("adminInquiriesPendingCount", list.filter((row) => !isAdminInquiryAnswered(row) && !isAdminInquiryDeleted(row)).length);
		setText("adminInquiriesAnsweredCount", list.filter(isAdminInquiryAnswered).length);
		setText("adminInquiriesDeletedCount", list.filter(isAdminInquiryDeleted).length);
		document.querySelectorAll("[data-admin-inquiry-view]").forEach((btn) => {
			btn.classList.toggle("active", btn.dataset.adminInquiryView === adminInquiryView);
		});
	}

	function renderAdminInquiryList(inquiries)
	{
		const listEl = document.getElementById("adminInquiryList");
		if (!listEl) return;
		const rows = Array.isArray(inquiries) ? inquiries : [];
		updateAdminInquiryFilterCounts(rows);
		const filteredRows = getAdminInquiryFilteredRows(rows);
		if (!rows.length) {
			listEl.innerHTML = '<div class="admin-empty">등록된 1:1 문의가 없습니다.</div>';
			return;
		}
		if (!filteredRows.length) {
			listEl.innerHTML = '<div class="admin-empty">해당 상태의 1:1 문의가 없습니다.</div>';
			return;
		}
		listEl.innerHTML = `
			<div class="my-suite-inquiry-list admin-inquiry-table">
				${filteredRows.map((row) => {
					const id = escapeAdminHtml(row.id || "");
					const deleted = isAdminInquiryDeleted(row);
					const answered = isAdminInquiryAnswered(row);
					const status = deleted ? "휴지통" : (answered ? "답변완료" : "답변대기");
					const rawAuthorName = String(row.author_name || "").trim();
					const rawAuthorEmail = String(row.author_email || "").trim();
					const rawAuthorFallback = String(row.author_label || "").trim();
					const authorBase = rawAuthorName || rawAuthorFallback || rawAuthorEmail || "작성자 미확인";
					const authorLabel = rawAuthorEmail && authorBase !== rawAuthorEmail ? `${authorBase}(${rawAuthorEmail})` : authorBase;
					return `
						<article class="my-suite-inquiry-item admin-inquiry-item ${deleted ? "deleted" : (answered ? "answered" : "pending")}" data-admin-inquiry-id="${id}">
							<div class="my-suite-inquiry-row admin-inquiry-row">
								<button type="button" class="my-suite-inquiry-main admin-inquiry-main-button" data-admin-inquiry-toggle="${id}">
									<span class="my-suite-inquiry-date admin-inquiry-date admin-inquiry-author-cell">${escapeAdminHtml(authorLabel)}</span>
									<span class="my-suite-inquiry-title admin-inquiry-title">${escapeAdminHtml(row.title || "제목 없음")}</span>
								</button>
								<div class="admin-inquiry-actions">
									<button type="button" class="my-suite-inquiry-state ${deleted ? "deleted" : (answered ? "answered" : "pending")}" data-admin-inquiry-toggle="${id}">${status}</button>
									${deleted ? "" : `<button type="button" class="my-suite-inquiry-delete admin-inquiry-delete" data-admin-inquiry-delete="${id}">삭제</button>`}
								</div>
							</div>
							<div class="my-suite-inquiry-detail admin-inquiry-detail">
								<div class="my-suite-inquiry-detail-block">
									<strong>작성자</strong>
									<p>${escapeAdminHtml(authorLabel)}</p>
								</div>
								<div class="my-suite-inquiry-detail-block">
									<strong>문의 내용</strong>
									<p>${escapeAdminHtml(row.message || "-")}</p>
									${row.created_at ? `<span>문의일 ${escapeAdminHtml(formatAdminInquiryDate(row.created_at))}</span>` : ""}
								</div>
								${answered || deleted ? `
									<div class="my-suite-inquiry-detail-block answer">
										<strong>관리자 답변</strong>
										<p>${answered ? escapeAdminHtml(row.admin_reply || "") : "등록된 답변이 없습니다."}</p>
										${row.replied_at ? `<span>답변일 ${escapeAdminHtml(formatAdminInquiryDate(row.replied_at))}</span>` : ""}
									</div>
								` : ""}
								${deleted ? "" : `
									<form class="my-suite-inquiry-reply-form" data-my-suite-inquiry-reply-form="${id}">
										<label class="my-suite-inquiry-label" for="adminInquiryReplyInput-${id}">관리자 답변</label>
										<textarea class="profile-suite-input my-suite-inquiry-reply-textarea" id="adminInquiryReplyInput-${id}" maxlength="1000" required>${escapeAdminHtml(row.admin_reply || "")}</textarea>
										<p class="my-suite-inquiry-reply-status" aria-live="polite"></p>
										<div class="my-suite-inquiry-reply-actions">
											<button type="submit" class="my-suite-inquiry-primary">${answered ? "답변 수정" : "답변 등록"}</button>
										</div>
									</form>
								`}
							</div>
						</article>
					`;
				}).join("")}
			</div>
		`;
	}

	async function deleteAdminInquiry(inquiryId)
	{
		const id = String(inquiryId || "").trim();
		if (!id) return;
		const client = getRealjejuSupabaseClient();
		if (!client || !isAdminUser(currentRealjejuAuthUser)) {
			openAuthErrorModal("관리자 로그인과 Supabase 연결을 확인하세요.", "1:1 문의내역", null);
			return;
		}
		try {
			const { error } = await client.rpc("admin_delete_support_inquiry", { p_inquiry_id: id });
			if (error) throw error;
			await loadAdminInquiries();
		}
		catch (err) {
			console.warn("관리자 1:1 문의 삭제 실패:", err);
			openAuthErrorModal(`문의 삭제에 실패했습니다${formatAdminRpcError(err)}. ${getAdminListingToolsSchemaHelp()}`, "1:1 문의내역", null);
		}
	}

	function confirmAdminInquiryDelete(inquiryId, returnFocusTarget)
	{
		openAuthConfirmModal(
			"선택한 1:1 문의를 삭제하시겠습니까?\n삭제된 문의는 휴지통으로 이동합니다.",
			"1:1 문의 삭제",
			() => deleteAdminInquiry(inquiryId),
			returnFocusTarget || null
		);
	}

	async function loadAdminInquiries()
	{
		const listEl = document.getElementById("adminInquiryList");
		if (!listEl) return;
		if (!isAdminUser(currentRealjejuAuthUser)) {
			listEl.innerHTML = '<div class="admin-empty">관리자 계정으로 로그인하세요.</div>';
			return;
		}
		const client = getRealjejuSupabaseClient();
		if (!client) {
			listEl.innerHTML = '<div class="admin-empty">Supabase 연결 설정을 확인하세요.</div>';
			return;
		}
		listEl.innerHTML = '<div class="admin-empty">1:1 문의내역을 불러오는 중입니다.</div>';
		try {
			await purgeAdminExpiredTrashIfNeeded(client);
			const inquiries = await fetchAdminInquiryRows(client);
			adminInquiryRowsCache = inquiries;
			renderAdminInquiryList(inquiries);
		} catch (err) {
			console.warn("관리자 1:1 문의내역 로드 실패:", err);
			listEl.innerHTML = `<div class="admin-empty">1:1 문의내역을 불러오지 못했습니다${escapeAdminHtml(formatAdminRpcError(err))}. ${escapeAdminHtml(getAdminRpcSchemaHelp())}</div>`;
		}
	}

	window.loadAdminInquiries = loadAdminInquiries;

	function isAdminProfileRow(row)
	{
		const role = String(row && (row.role || row.role_request) || "").trim().toLowerCase();
		return role === "admin";
	}

	function isAdminUserIncomplete(row)
	{
		if (!row) return true;
		if (row.profile_completed === false) return true;
		return !String(row.name || "").trim() || !String(row.phone || "").trim();
	}

		function getAdminUserFilteredRows(rows)
		{
			const list = Array.isArray(rows) ? rows : [];
			if (adminUserView === "deleted") return list.filter(isAdminUserWithdrawn);
			const visibleRows = list.filter((row) => !isAdminUserWithdrawn(row));
			if (adminUserView === "broker") return visibleRows.filter(isAdminUserApprovedBroker);
			if (adminUserView === "admin") return visibleRows.filter(isAdminProfileRow);
			if (adminUserView === "operator") return visibleRows.filter(isAdminUserOperatorRole);
			if (adminUserView === "incomplete") return visibleRows.filter(isAdminUserIncomplete);
			return visibleRows;
		}

	function updateAdminUserFilterCounts(rows, serverCounts = null)
	{
		const list = Array.isArray(rows) ? rows : [];
		const visibleRows = list.filter((row) => !isAdminUserWithdrawn(row));
		const setText = (id, value) => {
			const el = document.getElementById(id);
			if (el) el.textContent = String(value);
			};
			const counts = serverCounts && typeof serverCounts === "object" ? serverCounts : null;
			setText("adminUsersAllCount", counts ? Number(counts.all) || 0 : visibleRows.length);
			setText("adminUsersBrokerCount", counts ? Number(counts.broker) || 0 : visibleRows.filter(isAdminUserApprovedBroker).length);
			setText("adminUsersAdminCount", counts ? Number(counts.admin) || 0 : visibleRows.filter(isAdminProfileRow).length);
			setText("adminUsersOperatorCount", counts ? Number(counts.operator) || 0 : visibleRows.filter(isAdminUserOperatorRole).length);
			setText("adminUsersIncompleteCount", counts ? Number(counts.incomplete) || 0 : visibleRows.filter(isAdminUserIncomplete).length);
			setText("adminUsersDeletedCount", counts ? Number(counts.deleted) || 0 : list.filter(isAdminUserWithdrawn).length);
		document.querySelectorAll("[data-admin-user-view]").forEach((btn) => {
			btn.classList.toggle("active", btn.dataset.adminUserView === adminUserView);
		});
	}

	function normalizeAdminPagedPayload(value)
	{
		let payload = value;
		if (Array.isArray(payload) && payload.length === 1 && payload[0] && typeof payload[0] === "object") {
			payload = payload[0];
		}
		if (typeof payload === "string") {
			try {
				payload = JSON.parse(payload);
			} catch (_) {
				payload = {};
			}
		}
		payload = payload && typeof payload === "object" ? payload : {};
		const rows = Array.isArray(payload.rows) ? payload.rows : [];
		const totalCount = Math.max(0, Math.trunc(Number(payload.total_count) || 0));
		const totalPages = Math.max(1, Math.trunc(Number(payload.total_pages) || 1));
		const page = Math.min(totalPages, Math.max(1, Math.trunc(Number(payload.page) || 1)));
		return {
			rows,
			counts: payload.counts && typeof payload.counts === "object" ? payload.counts : {},
			totalCount,
			totalPages,
			page,
			perPage: Math.min(50, Math.max(1, Math.trunc(Number(payload.per_page) || 50)))
		};
	}

	function renderAdminPagedPagination(totalCount, totalPages, currentPage, dataAttribute, ariaLabel)
	{
		if (totalCount <= 50 || totalPages <= 1) return "";
		const items = getBrokerListingPaginationItems(totalPages, currentPage);
		return `
			<nav class="broker-listing-pagination" aria-label="${escapeAdminHtml(ariaLabel)}">
				${items.map((item) => {
					if (item === "ellipsis") return '<span class="broker-listing-page-ellipsis">…</span>';
					const page = Number(item);
					return `<button type="button" class="broker-listing-page-btn ${page === currentPage ? "active" : ""}" ${dataAttribute}="${page}" aria-current="${page === currentPage ? "page" : "false"}">${page}</button>`;
				}).join("")}
			</nav>
		`;
	}

	function formatAdminUserDate(row)
	{
		return formatBrokerListingDate(row && (row.created_at || row.privacy_agreed_at || row.updated_at));
	}

	function getLatestAdminUserDateValue(values)
	{
		let latestValue = "";
		let latestTime = 0;
		(Array.isArray(values) ? values : []).forEach((value) => {
			const text = String(value || "").trim();
			if (!text) return;
			const time = Date.parse(text);
			if (!Number.isFinite(time) || time <= latestTime) return;
			latestValue = text;
			latestTime = time;
		});
		return latestValue;
	}

		function formatAdminUserLastLoginDate(row)
		{
			if (!row) return "-";
			const userId = String(row.id || "").trim();
			const agencyId = String(row.agency_id || row.agencyId || row.approved_agency_id || "").trim();
			const email = String(row.email || "").trim().toLowerCase();
			const latestActivity = getLatestAdminUserDateValue([
				row.last_sign_in_at,
				row.last_login_at,
				row.last_seen_at,
				row.latest_listing_activity_at,
				row.last_listing_activity_at,
				userId ? adminUserListingActivityByUserId.get(userId) : "",
				agencyId ? adminUserListingActivityByAgencyId.get(agencyId) : "",
				email ? adminUserListingActivityByEmail.get(email) : ""
			]);
			return formatBrokerListingDate(latestActivity);
		}

		function normalizeAdminAgencyStatus(raw)
		{
			const compact = String(raw || "").trim().replace(/\s+/g, "").toLowerCase();
			if (!compact) return "";
			if (["active", "approved", "approve", "accepted", "승인", "승인완료", "완료"].includes(compact)) return "active";
			if (["pending", "waiting", "wait", "대기", "승인대기", "대기중", "new", "신청", "가입신청", "신청중"].includes(compact)) return "pending";
			if (["rejected", "reject", "denied", "거부", "반려", "승인거부"].includes(compact)) return "rejected";
			if (["deleted", "delete", "trash", "withdrawn", "삭제", "휴지통"].includes(compact)) return "deleted";
			return compact;
		}

		function getAdminUserAgencyStatus(row)
		{
			const rowStatus = normalizeAdminAgencyStatus(row && (row.approved_agency_status || row.agency_status || row.broker_office_status));
			if (rowStatus) return rowStatus;
			const userIdKey = String(row && row.id || "").trim();
			if (userIdKey && adminUserAgencyStatusByUserId.has(userIdKey)) return adminUserAgencyStatusByUserId.get(userIdKey);
			const emailKey = String(row && row.email || "").trim().toLowerCase();
			if (emailKey && adminUserAgencyStatusByEmail.has(emailKey)) return adminUserAgencyStatusByEmail.get(emailKey);
			return "";
		}

		function getAdminUserOfficeName(row)
		{
			const directName = String(row && (row.office_name || row.agency_office_name || row.broker_office_name) || "").trim();
			if (directName) return directName;
			const userIdKey = String(row && row.id || "").trim();
			if (userIdKey && adminUserAgencyOfficeNameByUserId.has(userIdKey)) {
				return adminUserAgencyOfficeNameByUserId.get(userIdKey);
			}
			const emailKey = String(row && row.email || "").trim().toLowerCase();
			if (emailKey && adminUserAgencyOfficeNameByEmail.has(emailKey)) {
				return adminUserAgencyOfficeNameByEmail.get(emailKey);
			}
			return "-";
		}

		function getAdminUserAgencyOwnerName(row)
		{
			const directName = String(row && (row.owner_name || row.agency_owner_name || row.broker_owner_name) || "").trim();
			if (directName) return directName;
			const userIdKey = String(row && row.id || "").trim();
			if (userIdKey && adminUserAgencyOwnerNameByUserId.has(userIdKey)) {
				return adminUserAgencyOwnerNameByUserId.get(userIdKey);
			}
			const emailKey = String(row && row.email || "").trim().toLowerCase();
			if (emailKey && adminUserAgencyOwnerNameByEmail.has(emailKey)) {
				return adminUserAgencyOwnerNameByEmail.get(emailKey);
			}
			return "";
		}

		function getAdminUserDisplayName(row)
		{
			const profileName = String(row && row.name || "").trim();
			const officeName = getAdminUserOfficeName(row);
			const ownerName = getAdminUserAgencyOwnerName(row);
			const normalizeName = (value) => String(value || "").trim().replace(/\s+/g, "").toLowerCase();
			if (officeName !== "-" && normalizeName(profileName) === normalizeName(officeName)) {
				return ownerName || "-";
			}
			return profileName || ownerName || "-";
		}




			function getAdminUserPassLabel(row)
			{
		const userId = String(row && row.id || "").trim();
		const entitlement = userId ? adminUserEntitlementByUserId.get(userId) : null;
		if (entitlement) {
			const label = String(entitlement.plan_label || entitlement.plan_key || "이용권 없음").trim();
			const status = String(entitlement.status || "").trim().toLowerCase();
			return status === "active" ? label : `${label} (${status === "expired" ? "만료" : "중지"})`;
		}
		const label = String(row && (row.pass_label || row.subscription_label || row.plan_label || row.membership_label || row.ticket_label) || "").trim();
		if (label) return label;
		const plan = String(row && (row.plan || row.subscription_plan || row.membership || row.ticket_type) || "").trim();
		if (!plan) return "-";
		if (plan === "starter") return "STARTER";
		if (plan === "premium") return "PREMIUM";
		if (plan === "pro") return "PRO";
			return plan;
		}

		function isMissingOperatorEntitlementSummaryRpc(error)
		{
			const code = String(error && error.code || "").trim().toUpperCase();
			const status = Number(error && error.status);
			const message = String(error && error.message || "").trim().toLowerCase();
			return status === 404
				|| code === "PGRST202"
				|| message.includes("get_operator_broker_entitlement_summaries_5165")
				|| message.includes("schema cache");
		}

		async function hydrateAdminUserEntitlementMap(client)
		{
			adminUserEntitlementByUserId = new Map();
			if (!client) return;
			try {
				const operatorReadOnly = isOperatorUser(currentRealjejuAuthUser)
					&& !isAdminUser(currentRealjejuAuthUser);
				const rpcName = operatorReadOnly
					? "get_operator_broker_entitlement_summaries_5165"
					: "get_admin_broker_entitlements";
				let { data, error } = await client.rpc(rpcName);
				if (operatorReadOnly && error && isMissingOperatorEntitlementSummaryRpc(error)) {
					({ data, error } = await client.rpc("get_operator_broker_entitlement_labels"));
				}
				if (error) throw error;
				(Array.isArray(data) ? data : []).forEach((row) => {
					const userId = String(row && row.user_id || "").trim();
					if (userId) adminUserEntitlementByUserId.set(userId, row);
				});
			} catch (error) {
				console.warn("관리자·운영자 회원 이용권 조회 실패:", error);
			}
		}

		function isAdminUserApprovedBroker(row)
		{
			if (!row || isAdminProfileRow(row) || isAdminUserWithdrawn(row)) return false;
			if (!isBrokerRoleValue(row.role_request || row.role)) return false;
			return normalizeAdminAgencyStatus(getAdminUserAgencyStatus(row)) === "active";
		}

		function getAdminUserRoleLabel(row)
		{
			return getAdminUserRoleLabels(row).join("\n");
		}

		function isAdminUserOperatorRole(row)
		{
			const roleValues = [row?.role_request, row?.role, row?.user_role, row?.app_role]
				.map((value) => String(value || "").trim().toLowerCase())
				.filter(Boolean);
			return roleValues.some((roleValue) => roleValue === "operator" || roleValue === "operations" || roleValue === "운영자")
				|| row?.is_operator === true
				|| row?.operator === true;
		}

		function getAdminUserRoleLabels(row)
		{
			if (isAdminProfileRow(row)) return ["관리자"];
			const labels = [];
			if (isBrokerRoleValue(row?.role_request)) labels.push(getRoleLabel(row.role_request));
			else if (isAdminUserApprovedBroker(row)) labels.push(getRoleLabel(row.role_request || row.role || "user"));
			if (isAdminUserOperatorRole(row)) labels.push("운영자");
			return labels.length ? Array.from(new Set(labels)) : ["일반회원"];
		}

		function getAdminUserRoleHtml(row)
		{
			return getAdminUserRoleLabels(row)
				.map((label) => `<span>${escapeAdminHtml(label)}</span>`)
				.join("");
		}

	function isAdminUserWithdrawn(row)
	{
		const status = String(row && row.status || "").trim().toLowerCase();
		return status === "deleted" || status === "withdrawn" || status === "blocked";
	}

	function getAdminUserProfileThumbHtml(row)
	{
		const url = String(row && (row.profile_image || row.profile_photo || row.avatar_url) || "").trim();
		if (url) return `<img src="${escapeAdminHtml(url)}" alt="회원 사진">`;
		const name = getAdminUserDisplayName(row) || String(row && row.email || "").trim();
		const initial = name ? name.slice(0, 1).toUpperCase() : "회";
		return `<span>${escapeAdminHtml(initial)}</span>`;
	}

	function renderAdminUsers(rows, options = {})
	{
		const listEl = document.getElementById("adminUsersList");
		if (!listEl) return;
		const operatorReadOnly = document.body.classList.contains("operator-page-open")
			&& !isAdminUser(currentRealjejuAuthUser);
		const list = Array.isArray(rows) ? rows : [];
		const serverPaged = options.serverPaged === true;
		updateAdminUserFilterCounts(list, serverPaged ? options.counts : null);
		const filteredRows = serverPaged ? list : getAdminUserFilteredRows(list);

		if (!list.length) {
			listEl.classList.remove("broker-listing-list");
			listEl.innerHTML = '<div class="admin-empty">등록된 회원이 없습니다.</div>';
			return;
		}
		if (!filteredRows.length) {
			listEl.classList.remove("broker-listing-list");
			listEl.innerHTML = '<div class="admin-empty">조건에 맞는 회원이 없습니다.</div>';
			return;
		}

		listEl.classList.add("broker-listing-list");
		window.realjejuAdminUserRowsById = new Map(list.map((row) => [String(row.id || row.email || ""), row]));
		listEl.innerHTML = `
			<div class="broker-listing-head admin-user-head">
				<div>사진</div>
				<div>가입일</div>
				<div>최근 로그인</div>
				<div>이름</div>
				<div>상호</div>
				<div>이메일</div>
				<div>연락처</div>
				<div>회원유형</div>
				<div>이용권</div>
				<div>상태</div>
				<div>관리</div>
			</div>
		` + filteredRows.map((row) => {
			const rowId = escapeAdminHtml(row.id || row.email || "");
				const name = getAdminUserDisplayName(row);
				const officeName = getAdminUserOfficeName(row);
				const email = String(row.email || "").trim() || "-";
				const phone = formatDisplayPhone(row.phone) || "";
				const roleLabel = getAdminUserRoleLabel(row);
			const passLabel = getAdminUserPassLabel(row);
			const withdrawn = isAdminUserWithdrawn(row);
			const profileState = isAdminProfileRow(row) ? "관리자" : (withdrawn ? "탈퇴" : (isAdminUserIncomplete(row) ? "미완료" : "완료"));
			const stateClass = isAdminProfileRow(row) ? "admin" : (withdrawn ? "deleted" : (isAdminUserIncomplete(row) ? "incomplete" : "published"));
				const canForceWithdraw = rowId && withdrawn === false;
				const canRestore = rowId && withdrawn === true && !isAdminProfileRow(row);
				const canPermanentDelete = rowId && withdrawn === true && !isAdminProfileRow(row);
			return `
				<div class="broker-listing-row admin-user-row" data-admin-user-id="${rowId}">
					<div class="broker-listing-cell broker-listing-photo-cell admin-user-thumb"><div class="broker-listing-thumb">${getAdminUserProfileThumbHtml(row)}</div></div>
					<div class="admin-user-cell broker-listing-meta">${escapeAdminHtml(formatAdminUserDate(row))}</div>
					<div class="admin-user-cell broker-listing-meta">${escapeAdminHtml(formatAdminUserLastLoginDate(row))}</div>
					<div class="admin-user-cell admin-user-name">${escapeAdminHtml(name)}</div>
					<div class="admin-user-cell admin-user-office" title="${escapeAdminHtml(officeName)}">${escapeAdminHtml(officeName)}</div>
					<div class="admin-user-cell admin-user-email">${escapeAdminHtml(email)}</div>
					<div class="admin-user-cell admin-user-phone">${escapeAdminHtml(phone)}</div>
					<div class="admin-user-cell admin-user-role">${getAdminUserRoleHtml(row)}</div>
					<div class="admin-user-cell admin-user-pass">${escapeAdminHtml(passLabel)}</div>
					<div class="admin-user-cell"><span class="broker-listing-status admin-user-profile-state ${escapeAdminHtml(stateClass)}">${escapeAdminHtml(profileState)}</span></div>
					<div class="broker-listing-menu-cell">
						<button type="button" class="broker-listing-menu-btn" data-admin-user-menu="${rowId}" aria-label="회원 관리 메뉴">⋮</button>
						<div class="broker-listing-more-menu" data-admin-user-menu-panel="${rowId}">
							<button type="button" class="broker-listing-menu-item" data-admin-user-action="view" data-user-id="${rowId}">상세 보기</button>
							${operatorReadOnly ? "" : `
								<button type="button" class="broker-listing-menu-item" data-admin-user-action="entitlement" data-user-id="${rowId}">이용권 수정</button>
								${canForceWithdraw ? `<button type="button" class="broker-listing-menu-item danger" data-admin-user-action="force_withdraw" data-user-id="${rowId}">강제탈퇴</button>` : ""}
								${canRestore ? `<button type="button" class="broker-listing-menu-item" data-admin-user-action="restore" data-user-id="${rowId}">복원</button>` : ""}
								${canPermanentDelete ? `<button type="button" class="broker-listing-menu-item danger" data-admin-user-action="permanent_delete" data-user-id="${rowId}">영구삭제</button>` : ""}
							`}
						</div>
					</div>
				</div>
			`;
		}).join("") + (serverPaged ? renderAdminPagedPagination(
			Number(options.totalCount) || 0,
			Number(options.totalPages) || 1,
			Number(options.page) || 1,
			"data-admin-user-page",
			"회원 관리 페이지"
		) : "");
	}

	function openAdminUserDetail(userId, returnFocusTarget)
	{
		const row = window.realjejuAdminUserRowsById?.get(String(userId || ""));
		if (!row) return;
		const lines = [
				`이름 : ${getAdminUserDisplayName(row)}`,
			`상호 : ${getAdminUserOfficeName(row)}`,
			`이메일 : ${String(row.email || "-").trim()}`,
				`연락처 : ${formatDisplayPhone(row.phone) || ""}`,
				`회원유형 : ${getAdminUserRoleLabel(row)}`,
			`이용권 : ${getAdminUserPassLabel(row)}`,
			`상태 : ${isAdminProfileRow(row) ? "관리자" : (isAdminUserWithdrawn(row) ? "탈퇴" : (isAdminUserIncomplete(row) ? "미완료" : "완료"))}`,
			`가입일 : ${formatAdminUserDate(row)}`,
			`최근 로그인 : ${formatAdminUserLastLoginDate(row)}`
		];
		openAuthErrorModal(lines.join("\n"), "회원 상세", returnFocusTarget || null);
	}

	let adminEntitlementReturnFocusTarget = null;

	function isAdminEntitlementBrokerRow(row)
	{
		if (!row || isAdminUserWithdrawn(row)) return false;
		return normalizeAdminAgencyStatus(getAdminUserAgencyStatus(row)) === "active"
			|| getAdminUserOfficeName(row) !== "-"
			|| isBrokerRoleValue(row.role_request || row.role);
	}

	function getAdminEntitlementDateInputValue(value)
	{
		const date = new Date(value || "");
		if (Number.isNaN(date.getTime())) return "";
		const parts = new Intl.DateTimeFormat("en-CA", {
			timeZone: "Asia/Seoul",
			year: "numeric",
			month: "2-digit",
			day: "2-digit"
		}).formatToParts(date);
		const getPart = (type) => parts.find((part) => part.type === type)?.value || "";
		return `${getPart("year")}-${getPart("month")}-${getPart("day")}`;
	}

	function closeAdminEntitlementModal()
	{
		const modal = document.getElementById("adminEntitlementModal");
		if (!modal) return;
		modal.classList.remove("open");
		modal.setAttribute("aria-hidden", "true");
		if (adminEntitlementReturnFocusTarget && typeof adminEntitlementReturnFocusTarget.focus === "function") {
			adminEntitlementReturnFocusTarget.focus();
		}
		adminEntitlementReturnFocusTarget = null;
	}

	function applyAdminEntitlementPlanPreset(planKey)
	{
		const preset = {
			none: { listings: 0, premium: 0, relist: 0, contracts: 0, status: "inactive" },
			starter: { listings: 100, premium: 0, relist: 20, contracts: 0, status: "active" },
			premium: { listings: 300, premium: 20, relist: 50, contracts: 100, status: "active" },
			pro: { listings: 500, premium: 50, relist: 100, contracts: 300, status: "active" }
		}[String(planKey || "")];
		if (!preset) return;
		const setValue = (id, value) => {
			const input = document.getElementById(id);
			if (input) input.value = String(value);
		};
		setValue("adminEntitlementListingLimit", preset.listings);
		setValue("adminEntitlementPremiumLimit", preset.premium);
		setValue("adminEntitlementRelistLimit", preset.relist);
		setValue("adminEntitlementContractLimit", preset.contracts);
		setValue("adminEntitlementStatus", preset.status);
	}

	function ensureAdminEntitlementModal()
	{
		let modal = document.getElementById("adminEntitlementModal");
		if (modal) return modal;
		modal = document.createElement("div");
		modal.className = "admin-entitlement-modal";
		modal.id = "adminEntitlementModal";
		modal.setAttribute("aria-hidden", "true");
		modal.innerHTML = `
			<div class="admin-entitlement-dialog" role="dialog" aria-modal="true" aria-labelledby="adminEntitlementTitle">
				<div class="admin-entitlement-dialog-head">
					<div>
						<h2 id="adminEntitlementTitle">중개사 이용권 수정</h2>
						<p id="adminEntitlementMemberLabel"></p>
					</div>
					<button type="button" class="admin-entitlement-close" data-admin-entitlement-close aria-label="닫기">×</button>
				</div>
				<form class="admin-entitlement-form" id="adminEntitlementForm">
					<input type="hidden" id="adminEntitlementUserId">
					<label class="admin-entitlement-field">
						<span>이용권</span>
						<select id="adminEntitlementPlanKey">
							<option value="none">이용권 없음</option>
							<option value="starter">베이직 플랜</option>
							<option value="premium">프리미엄 플랜</option>
							<option value="pro">프로 플랜</option>
							<option value="custom">직접 설정</option>
						</select>
					</label>
					<label class="admin-entitlement-field">
						<span>상태</span>
						<select id="adminEntitlementStatus">
							<option value="active">이용중</option>
							<option value="inactive">미사용</option>
							<option value="suspended">중지</option>
							<option value="cancelled">취소</option>
							<option value="expired">만료</option>
						</select>
					</label>
					<label class="admin-entitlement-field">
						<span>시작일</span>
						<input type="date" id="adminEntitlementStartsAt" required>
					</label>
					<label class="admin-entitlement-field">
						<span>종료일</span>
						<input type="date" id="adminEntitlementEndsAt" required>
					</label>
					<label class="admin-entitlement-field">
						<span>일반매물 한도</span>
						<input type="number" id="adminEntitlementListingLimit" min="0" step="1" required>
					</label>
					<label class="admin-entitlement-field">
						<span>프리미엄 매물 한도</span>
						<input type="number" id="adminEntitlementPremiumLimit" min="0" step="1" required>
					</label>
					<label class="admin-entitlement-field">
						<span>하루 재등록 한도</span>
						<input type="number" id="adminEntitlementRelistLimit" min="0" step="1" required>
					</label>
					<label class="admin-entitlement-field">
						<span>계약서 보관 한도</span>
						<input type="number" id="adminEntitlementContractLimit" min="0" step="1" required>
					</label>
					<label class="admin-entitlement-field">
						<span>계약서 보관 사용중</span>
						<input type="number" id="adminEntitlementContractUsed" min="0" step="1" required>
					</label>
					<p class="admin-entitlement-status" id="adminEntitlementSaveStatus" aria-live="polite"></p>
					<div class="admin-entitlement-actions">
						<button type="button" data-admin-entitlement-close>취소</button>
						<button type="submit">저장</button>
					</div>
				</form>
			</div>
		`;
		document.body.appendChild(modal);
		modal.querySelectorAll("[data-admin-entitlement-close]").forEach((button) => {
			button.addEventListener("click", closeAdminEntitlementModal);
		});
		modal.addEventListener("click", (event) => {
			if (event.target === modal) closeAdminEntitlementModal();
		});
		modal.querySelector("#adminEntitlementPlanKey")?.addEventListener("change", (event) => {
			applyAdminEntitlementPlanPreset(event.target.value);
		});
		modal.querySelector("#adminEntitlementForm")?.addEventListener("submit", async (event) => {
			event.preventDefault();
			await saveAdminBrokerEntitlement();
		});
		return modal;
	}

	function openAdminEntitlementModal(userId, returnFocusTarget)
	{
		const id = String(userId || "").trim();
		const row = window.realjejuAdminUserRowsById?.get(id);
		if (!id || !row) return;
		const entitlement = adminUserEntitlementByUserId.get(id) || null;
		const modal = ensureAdminEntitlementModal();
		adminEntitlementReturnFocusTarget = returnFocusTarget || null;
		const today = new Date();
		const defaultEnd = new Date("2026-12-31T23:59:59+09:00");
		const setValue = (fieldId, value) => {
			const input = modal.querySelector(`#${fieldId}`);
			if (input) input.value = String(value ?? "");
		};
		setValue("adminEntitlementUserId", id);
		setValue("adminEntitlementPlanKey", entitlement?.plan_key || (isAdminEntitlementBrokerRow(row) ? "premium" : "none"));
		setValue("adminEntitlementStatus", entitlement?.status || (isAdminEntitlementBrokerRow(row) ? "active" : "inactive"));
		setValue("adminEntitlementStartsAt", getAdminEntitlementDateInputValue(entitlement?.starts_at || today));
		setValue("adminEntitlementEndsAt", getAdminEntitlementDateInputValue(entitlement?.ends_at || defaultEnd));
		setValue("adminEntitlementListingLimit", entitlement?.listing_limit ?? (isAdminEntitlementBrokerRow(row) ? 300 : 0));
		setValue("adminEntitlementPremiumLimit", entitlement?.premium_limit ?? (isAdminEntitlementBrokerRow(row) ? 20 : 0));
		setValue("adminEntitlementRelistLimit", entitlement?.relist_daily_limit ?? (isAdminEntitlementBrokerRow(row) ? 50 : 0));
		setValue("adminEntitlementContractLimit", entitlement?.contract_limit ?? (isAdminEntitlementBrokerRow(row) ? 100 : 0));
		setValue("adminEntitlementContractUsed", entitlement?.contract_used ?? 0);
		const memberLabel = modal.querySelector("#adminEntitlementMemberLabel");
		if (memberLabel) memberLabel.textContent = `${getAdminUserDisplayName(row)} · ${String(row.email || "-")}`;
		const status = modal.querySelector("#adminEntitlementSaveStatus");
		if (status) status.textContent = "";
		modal.classList.add("open");
		modal.setAttribute("aria-hidden", "false");
		setTimeout(() => modal.querySelector("#adminEntitlementPlanKey")?.focus(), 0);
	}

	async function saveAdminBrokerEntitlement()
	{
		const modal = document.getElementById("adminEntitlementModal");
		if (!modal || !isAdminUser(currentRealjejuAuthUser)) return;
		const getValue = (id) => String(modal.querySelector(`#${id}`)?.value || "").trim();
		const userId = getValue("adminEntitlementUserId");
		const statusEl = modal.querySelector("#adminEntitlementSaveStatus");
		const startsAt = getValue("adminEntitlementStartsAt");
		const endsAt = getValue("adminEntitlementEndsAt");
		if (!userId || !startsAt || !endsAt) {
			if (statusEl) statusEl.textContent = "회원과 이용 기간을 확인하세요.";
			return;
		}
		const client = getRealjejuSupabaseClient();
		if (!client) {
			if (statusEl) statusEl.textContent = "Supabase 연결 설정을 확인하세요.";
			return;
		}
		if (statusEl) statusEl.textContent = "저장 중입니다.";
		try {
			const { error } = await client.rpc("admin_set_broker_entitlement", {
				p_user_id: userId,
				p_plan_key: getValue("adminEntitlementPlanKey"),
				p_status: getValue("adminEntitlementStatus"),
				p_starts_at: `${startsAt}T00:00:00+09:00`,
				p_ends_at: `${endsAt}T23:59:59+09:00`,
				p_listing_limit: normalizeRealjejuNonnegativeCount(getValue("adminEntitlementListingLimit")),
				p_premium_limit: normalizeRealjejuNonnegativeCount(getValue("adminEntitlementPremiumLimit")),
				p_relist_daily_limit: normalizeRealjejuNonnegativeCount(getValue("adminEntitlementRelistLimit")),
				p_contract_limit: normalizeRealjejuNonnegativeCount(getValue("adminEntitlementContractLimit")),
				p_contract_used: normalizeRealjejuNonnegativeCount(getValue("adminEntitlementContractUsed"))
			});
			if (error) throw error;
			await hydrateAdminUserEntitlementMap(client);
			if (Array.isArray(adminUserRowsCache)) renderAdminUsers(adminUserRowsCache);
			closeAdminEntitlementModal();
			openAuthErrorModal("중개사 이용권과 한도를 저장했습니다.", "이용권 수정", null);
		} catch (error) {
			console.error("관리자 이용권 저장 실패:", error);
			if (statusEl) statusEl.textContent = `저장하지 못했습니다. sql/broker_entitlements_5.118.sql 적용 상태를 확인하세요${formatAdminRpcError(error)}.`;
		}
	}

