	async function loadAdminUsers(options = {})
	{
		const listEl = document.getElementById("adminUsersList");
		if (!listEl) return;
		if (!isAdminUser(currentRealjejuAuthUser) && !isOperatorUser(currentRealjejuAuthUser)) {
			listEl.classList.remove("broker-listing-list");
			listEl.innerHTML = '<div class="admin-empty">관리자 또는 운영자 계정에서만 이용 가능합니다.</div>';
			return;
		}
		const client = getRealjejuSupabaseClient();
		if (!client) {
			listEl.classList.remove("broker-listing-list");
			listEl.innerHTML = '<div class="admin-empty">Supabase 연결 설정을 확인하세요.</div>';
			return;
		}

		const requestKey = `${adminUserView}:${adminUserPage}`;
		if (
			Array.isArray(adminUserRowsCache)
			&& adminUserPageMeta
			&& adminUserPageMeta.requestKey === requestKey
			&& options.force !== true
		) {
			renderAdminUsers(adminUserRowsCache, {
				serverPaged: true,
				...adminUserPageMeta
			});
			return;
		}

		if (adminUserLoadPromise) return adminUserLoadPromise;

		if (!options.silent && !listEl.querySelector(".admin-user-row")) {
			listEl.classList.remove("broker-listing-list");
			listEl.innerHTML = '<div class="admin-empty">회원 목록을 불러오는 중입니다.</div>';
		}

		adminUserLoadPromise = (async () => {
			await purgeAdminExpiredTrashIfNeeded(client);
			const { data, error } = await client.rpc("get_admin_users_page_5142", {
				p_view: adminUserView,
				p_page: adminUserPage,
				p_per_page: ADMIN_USERS_PER_PAGE
			});

			if (error) {
				console.error("관리자 회원 목록 조회 실패:", error);
				adminUserAgencyStatusByUserId = new Map();
				adminUserAgencyStatusByEmail = new Map();
				adminUserAgencyOfficeNameByUserId = new Map();
				adminUserAgencyOfficeNameByEmail = new Map();
				adminUserAgencyOwnerNameByUserId = new Map();
				adminUserAgencyOwnerNameByEmail = new Map();
				adminUserListingActivityByUserId = new Map();
				adminUserListingActivityByAgencyId = new Map();
				adminUserListingActivityByEmail = new Map();
				listEl.innerHTML = `<div class="admin-empty">회원 목록을 불러오지 못했습니다${escapeAdminHtml(formatAdminRpcError(error))}. sql/admin_member_application_pagination_5.142.sql 적용 상태를 확인하세요.</div>`;
				return;
			}

			const payload = normalizeAdminPagedPayload(data);
			if (adminUserPage > payload.totalPages) {
				adminUserPage = payload.totalPages;
				adminUserRowsCache = null;
				adminUserPageMeta = null;
				setTimeout(() => void loadAdminUsers({ force: true, silent: options.silent }), 0);
				return;
			}
			adminUserPage = payload.page;
			adminUserRowsCache = payload.rows;
			adminUserPageMeta = {
				requestKey: `${adminUserView}:${adminUserPage}`,
				counts: payload.counts,
				totalCount: payload.totalCount,
				totalPages: payload.totalPages,
				page: payload.page
			};
			renderAdminUsers(adminUserRowsCache, {
				serverPaged: true,
				...adminUserPageMeta
			});
		})().catch((err) => {
			console.error("관리자 회원 목록 오류:", err);
			adminUserAgencyStatusByUserId = new Map();
			adminUserAgencyStatusByEmail = new Map();
			adminUserAgencyOfficeNameByUserId = new Map();
			adminUserAgencyOfficeNameByEmail = new Map();
			adminUserAgencyOwnerNameByUserId = new Map();
			adminUserAgencyOwnerNameByEmail = new Map();
			adminUserListingActivityByUserId = new Map();
			adminUserListingActivityByAgencyId = new Map();
			adminUserListingActivityByEmail = new Map();
			listEl.classList.remove("broker-listing-list");
			listEl.innerHTML = '<div class="admin-empty">회원 처리 중 오류가 발생했습니다.</div>';
		}).finally(() => {
			adminUserLoadPromise = null;
		});
		return adminUserLoadPromise;
	}

	window.loadAdminUsers = loadAdminUsers;

	function isAdminListingReported(row)
	{
		const payload = row && row.payload && typeof row.payload === "object" ? row.payload : {};
		const status = String(row?.status || "").toLowerCase();
		return status === "reported"
			|| payload.reported === true
			|| payload.is_reported === true
			|| Number(payload.report_count || payload.reports_count || 0) > 0
			|| !!(payload.reported_at || payload.last_reported_at);
	}

	function isAdminListingDeleted(row)
	{
		return getBrokerListingEffectiveStatus(row) === "deleted";
	}

	function getAdminListingActiveRows(rows)
	{
		return (Array.isArray(rows) ? rows : []).filter((row) => !isAdminListingDeleted(row));
	}

	function getAdminListingVisibleRows(rows)
	{
		return getAdminListingActiveRows(rows).filter((row) => {
			const status = getBrokerListingEffectiveStatus(row);
			return !["closed", "hidden", "archive"].includes(status);
		});
	}

	function getAdminListingFilteredRows(rows)
	{
		const list = Array.isArray(rows) ? rows : [];
		const applySearch = (sourceRows) => filterAdminListingRowsBySearch(sourceRows);
		const applyFilters = (sourceRows) => applyAdminListingAdvancedFilters(applySearch(sourceRows));
		if (adminListingView === "deleted") return applyFilters(list.filter(isAdminListingDeleted));
		const activeRows = getAdminListingActiveRows(list);
		if (adminListingView === "reported") return applyFilters(activeRows.filter(isAdminListingReported));
		if (adminListingView === "closed") return applyFilters(activeRows.filter((row) => getBrokerListingEffectiveStatus(row) === "closed"));
		if (adminListingView === "hidden") return applyFilters(activeRows.filter((row) => ["hidden", "archive"].includes(getBrokerListingEffectiveStatus(row))));
		return applyFilters(getAdminListingVisibleRows(list));
	}

	function getAdminListingSearchQuery()
	{
		const input = document.getElementById("adminListingTopbarSearchInput");
		const value = input ? input.value : adminListingSearchQuery;
		adminListingSearchQuery = String(value || "").replace(/\s+/g, " ").trim();
		return adminListingSearchQuery;
	}

	function getAdminListingSearchText(row)
	{
		const priceInfo = getBrokerListingDealPrice(row);
		const payload = row && row.payload && typeof row.payload === "object" ? row.payload : {};
		return [
			row && row.title,
			row && row.public_address,
			row && row.address1,
			row && row.property_type_label,
			row && row.property_type,
			getBrokerListingNo(row),
			getBrokerListingStatusLabel(getBrokerListingEffectiveStatus(row)),
			getBrokerListingAreaValue(row),
			priceInfo && priceInfo.dealLabel,
			priceInfo && priceInfo.priceLabel,
			payload && payload.memo,
			payload && payload.broker_memo,
			payload && payload.address,
			payload && payload.detail_address
		].map((value) => String(value || "").toLowerCase()).join(" ");
	}

	function filterAdminListingRowsBySearch(rows)
	{
		const sourceRows = Array.isArray(rows) ? rows : [];
		const query = getAdminListingSearchQuery().toLowerCase();
		if (!query) return sourceRows;
		const terms = query.split(/\s+/).filter(Boolean);
		if (!terms.length) return sourceRows;
		return sourceRows.filter((row) => {
			const text = getAdminListingSearchText(row);
			return terms.every((term) => text.includes(term));
		});
	}

	function getAdminListingFilterMenuId(type)
	{
		return {
			property: "adminListingPropertyTypeFilterMenu",
			deal: "adminListingPriceTypeFilterMenu",
			area: "adminListingAreaFilterMenu",
			landType: "adminListingLandTypeFilterMenu",
			landUseZone: "adminListingLandUseZoneFilterMenu"
		}[type] || "";
	}

	function getAdminListingFilterBtnId(type)
	{
		return {
			property: "adminListingPropertyTypeFilterBtn",
			deal: "adminListingPriceTypeFilterBtn",
			area: "adminListingAreaFilterBtn",
			landType: "adminListingLandTypeFilterBtn",
			landUseZone: "adminListingLandUseZoneFilterBtn"
		}[type] || "";
	}

	function getAdminListingFilterFallbackLabel(type)
	{
		return {
			property: "매물 유형",
			deal: "가격 유형",
			area: "면적",
			landType: "지목",
			landUseZone: "용도지역"
		}[type] || "필터";
	}

	function getAdminListingFilterTargetSet(type)
	{
		return {
			property: adminListingPropertyFilter,
			deal: adminListingDealFilter,
			landType: adminListingLandTypeFilter,
			landUseZone: adminListingLandUseZoneFilter
		}[type] || adminListingPropertyFilter;
	}

	function normalizeAdminListingFilterType(value)
	{
		return ["property", "deal", "landType", "landUseZone"].includes(value) ? value : "property";
	}

	function getAdminListingCompactFilterLabel(values, fallback, labelGetter, visibleCount = 2)
	{
		const list = Array.from(values || []).map((value) => labelGetter ? labelGetter(value) : value).filter(Boolean);
		if (!list.length) return fallback;
		if (list.length <= visibleCount) return list.join(", ");
		return `${list.slice(0, visibleCount).join(", ")} +${list.length - visibleCount}`;
	}

	function renderAdminListingFilterMenu(type, sections, menuTitle = "")
	{
		return renderBrokerHomeFilterMenu(type, sections, menuTitle)
			.replaceAll("data-broker-home-filter-option", "data-admin-listing-filter-option")
			.replaceAll("data-broker-home-filter-reset", "data-admin-listing-filter-reset");
	}

	function getAdminListingAreaMaxM2(range = adminListingAreaRange)
	{
		return range && range.land === true ? AREA_FILTER_LAND_MAX_M2 : AREA_FILTER_MAX_M2;
	}

	function getAdminListingAreaUnit(range = adminListingAreaRange)
	{
		return range && range.unit === "py" ? "py" : "m2";
	}

	function getAdminListingAreaUnitLabel(range = adminListingAreaRange)
	{
		return getAdminListingAreaUnit(range) === "py" ? "평" : "㎡";
	}

	function getAdminListingAreaNextUnitLabel(range = adminListingAreaRange)
	{
		return getAdminListingAreaUnit(range) === "py" ? "㎡" : "평";
	}

	function getAdminListingAreaUnitMax(range = getAdminListingAreaRange())
	{
		const unit = getAdminListingAreaUnit(range);
		return range && range.land === true
			? (unit === "py" ? AREA_FILTER_LAND_MAX_PY : AREA_FILTER_LAND_MAX_M2)
			: (unit === "py" ? AREA_FILTER_MAX_PY : AREA_FILTER_MAX_M2);
	}

	function getAdminListingAreaRange()
	{
		const range = adminListingAreaRange && typeof adminListingAreaRange === "object" ? adminListingAreaRange : {};
		const land = range.land === true;
		const maxM2 = getAdminListingAreaMaxM2({ land });
		const min = Math.max(0, Math.min(maxM2, Number(range.min) || 0));
		const rawMax = Number(range.max);
		const max = Math.max(0, Math.min(maxM2, Number.isFinite(rawMax) ? rawMax : maxM2));
		adminListingAreaRange = {
			min: Math.min(min, max),
			max: Math.max(min, max),
			exclusive: land ? false : range.exclusive !== false,
			land,
			unit: range.unit === "py" ? "py" : "m2"
		};
		return adminListingAreaRange;
	}

	function isAdminListingAreaRangeActive(range = getAdminListingAreaRange())
	{
		const maxM2 = getAdminListingAreaMaxM2(range);
		return Number(range.min) > 0 || Number(range.max) < maxM2 - AREA_FILTER_MAX_EDGE_EPSILON_M2 || range.land === true;
	}

	function formatAdminListingAreaRangeSummary(range = getAdminListingAreaRange())
	{
		if (!isAdminListingAreaRangeActive(range)) return "전체";
		const unit = getAdminListingAreaUnit(range);
		const unitLabel = getAdminListingAreaUnitLabel(range);
		const maxM2 = getAdminListingAreaMaxM2(range);
		const minLabel = Number(range.min) <= 0 ? "최소" : `${Math.round(areaFilterFromM2(range.min, unit)).toLocaleString("ko-KR")}${unitLabel}`;
		const maxLabel = Number(range.max) >= maxM2 - AREA_FILTER_MAX_EDGE_EPSILON_M2 ? "최대" : `${Math.round(areaFilterFromM2(range.max, unit)).toLocaleString("ko-KR")}${unitLabel}`;
		const prefix = range.exclusive && !range.land ? "전용 " : "";
		return `${prefix}${minLabel}~${maxLabel}`;
	}

	function getAdminListingAreaScaleHtml(range = getAdminListingAreaRange())
	{
		const unit = getAdminListingAreaUnit(range);
		const unitLabel = getAdminListingAreaUnitLabel(range);
		const values = range.land
			? (unit === "py" ? [100, 200, 300, 400] : [330, 660, 990, 1320])
			: (unit === "py" ? [10, 20, 30, 40] : [33, 66, 99, 132]);
		const labels = ["최소", ...values.map(value => `${value}${unitLabel}`), "최대"];
		const lastIndex = Math.max(1, labels.length - 1);
		return labels
			.map((label, index) => `<span style="left:${(index / lastIndex) * 100}%;">${label}</span>`)
			.join("");
	}

	function renderAdminListingAreaFilterMenu()
	{
		return `
			<h3 class="area-filter-title">면적</h3>
			<div class="area-filter-summary-row">
				<strong class="area-filter-summary" id="adminListingAreaFilterSummaryText">전체</strong>
				<button type="button" class="area-filter-icon-btn area-filter-manual-btn" aria-label="면적 직접 입력">
					<i class="fa-solid fa-pen" aria-hidden="true"></i>
				</button>
				<button type="button" class="area-filter-unit-btn" id="adminListingAreaFilterUnitToggleBtn" aria-label="면적 단위 전환">
					<i class="fa-solid fa-arrows-rotate" aria-hidden="true"></i>
					<span id="adminListingAreaFilterUnitToggleText">평</span>
				</button>
				<button type="button" class="area-filter-icon-btn area-filter-reset-btn" id="adminListingAreaFilterResetBtn" aria-label="면적 초기화" hidden>
					<i class="fa-solid fa-rotate-right" aria-hidden="true"></i>
				</button>
			</div>
			<div class="area-filter-slider-wrap">
				<div class="area-filter-slider-rail" id="adminListingAreaFilterSliderRail">
					<div class="area-filter-slider-fill" id="adminListingAreaFilterSliderFill"></div>
					<input type="range" class="area-filter-range area-filter-range-min" id="adminListingAreaFilterMinRange" min="0" max="${AREA_FILTER_MAX_M2}" step="1" value="0" aria-label="최소 면적" />
					<input type="range" class="area-filter-range area-filter-range-max" id="adminListingAreaFilterMaxRange" min="0" max="${AREA_FILTER_MAX_M2}" step="1" value="${AREA_FILTER_MAX_M2}" aria-label="최대 면적" />
				</div>
				<div class="area-filter-scale" id="adminListingAreaFilterScale">${getAdminListingAreaScaleHtml()}</div>
			</div>
			<div class="area-filter-target-options">
				<label class="area-filter-exclusive-option">
					<input type="checkbox" id="adminListingAreaFilterExclusiveChk" checked />
					<span>전용면적 기준으로 찾기</span>
				</label>
				<label class="area-filter-exclusive-option">
					<input type="checkbox" id="adminListingAreaFilterLandChk" />
					<span>토지</span>
				</label>
			</div>
		`;
	}

	function syncAdminListingAreaFilterUi()
	{
		const range = getAdminListingAreaRange();
		const minInput = document.getElementById("adminListingAreaFilterMinRange");
		const maxInput = document.getElementById("adminListingAreaFilterMaxRange");
		const fill = document.getElementById("adminListingAreaFilterSliderFill");
		const summary = document.getElementById("adminListingAreaFilterSummaryText");
		const exclusive = document.getElementById("adminListingAreaFilterExclusiveChk");
		const land = document.getElementById("adminListingAreaFilterLandChk");
		const reset = document.getElementById("adminListingAreaFilterResetBtn");
		const unitText = document.getElementById("adminListingAreaFilterUnitToggleText");
		const scale = document.getElementById("adminListingAreaFilterScale");
		const unit = getAdminListingAreaUnit(range);
		const unitMax = getAdminListingAreaUnitMax(range);
		const maxM2 = getAdminListingAreaMaxM2(range);
		const minUnitValue = Number.isFinite(range.min) ? areaFilterFromM2(range.min, unit) : 0;
		const maxUnitValue = Number(range.max) >= maxM2 - AREA_FILTER_MAX_EDGE_EPSILON_M2 ? unitMax : areaFilterFromM2(range.max, unit);
		[minInput, maxInput].forEach(input => {
			if (!input) return;
			input.min = "0";
			input.max = String(unitMax);
			input.step = "0.01";
		});
		if (minInput) minInput.value = String(Math.max(0, Math.min(unitMax, minUnitValue || 0)));
		if (maxInput) maxInput.value = String(Math.max(0, Math.min(unitMax, maxUnitValue || unitMax)));
		if (fill) {
			const left = unitMax > 0 ? ((minUnitValue || 0) / unitMax) * 100 : 0;
			const right = unitMax > 0 ? ((maxUnitValue || unitMax) / unitMax) * 100 : 100;
			fill.style.left = `${left}%`;
			fill.style.width = `${Math.max(0, right - left)}%`;
		}
		if (summary) summary.textContent = formatAdminListingAreaRangeSummary(range);
		if (exclusive) exclusive.checked = range.exclusive;
		if (land) land.checked = range.land;
		if (unitText) unitText.textContent = getAdminListingAreaNextUnitLabel(range);
		if (scale) scale.innerHTML = getAdminListingAreaScaleHtml(range);
		if (reset) {
			const active = isAdminListingAreaRangeActive(range);
			reset.hidden = !active;
			reset.classList.toggle("is-visible", active);
		}
	}

	function updateAdminListingAreaRangeFromControls(activeInput = document.activeElement)
	{
		const minInput = document.getElementById("adminListingAreaFilterMinRange");
		const maxInput = document.getElementById("adminListingAreaFilterMaxRange");
		const exclusive = document.getElementById("adminListingAreaFilterExclusiveChk");
		const land = document.getElementById("adminListingAreaFilterLandChk");
		const current = getAdminListingAreaRange();
		let nextLand = current.land === true;
		if (activeInput === land) nextLand = true;
		else if (activeInput === exclusive) nextLand = false;
		const nextRangeShape = { ...current, land: nextLand };
		const modeChanged = nextLand !== current.land;
		const unit = getAdminListingAreaUnit(current);
		const unitMax = getAdminListingAreaUnitMax(nextRangeShape);
		const maxM2 = getAdminListingAreaMaxM2(nextRangeShape);
		let min = Number(minInput?.value ?? areaFilterFromM2(current.min, unit));
		let max = Number(maxInput?.value ?? areaFilterFromM2(current.max, unit));
		if (!Number.isFinite(min)) min = 0;
		if (!Number.isFinite(max)) max = unitMax;
		const gap = typeof getBrokerHomeAreaThumbGapValue === "function" ? getBrokerHomeAreaThumbGapValue() : 1;
		if (modeChanged) {
			min = 0;
			max = unitMax;
		}
		else if (activeInput === minInput) {
			min = Math.min(min, Math.max(0, max - gap));
			if (minInput) minInput.value = String(min);
		}
		else if (activeInput === maxInput) {
			max = Math.max(max, Math.min(unitMax, min + gap));
			if (maxInput) maxInput.value = String(max);
		}
		else if (min + gap > max) {
			max = Math.min(unitMax, min + gap);
			if (max >= unitMax) min = Math.max(0, max - gap);
			if (minInput) minInput.value = String(min);
			if (maxInput) maxInput.value = String(max);
		}
		const minM2 = modeChanged ? 0 : areaFilterToM2(min, unit);
		const maxM2Value = modeChanged || max >= unitMax - 0.01 ? maxM2 : areaFilterToM2(max, unit);
		adminListingAreaRange = {
			min: Math.max(0, Math.min(maxM2, Number(minM2) || 0)),
			max: Math.max(0, Math.min(maxM2, Number(maxM2Value) || maxM2)),
			exclusive: !nextLand,
			land: nextLand,
			unit: current.unit
		};
		syncAdminListingAreaFilterUi();
	}

	function resetAdminListingAreaRange()
	{
		const unit = getAdminListingAreaUnit(getAdminListingAreaRange());
		adminListingAreaRange = { min: 0, max: AREA_FILTER_MAX_M2, exclusive: true, land: false, unit };
		syncAdminListingAreaFilterUi();
	}

	function populateAdminListingFilterMenus()
	{
		const propertyMenu = document.getElementById("adminListingPropertyTypeFilterMenu");
		if (propertyMenu) propertyMenu.innerHTML = renderAdminListingFilterMenu("property", getBrokerHomePropertyTypeSections());
		const dealMenu = document.getElementById("adminListingPriceTypeFilterMenu");
		if (dealMenu) {
			const deals = [
				{ value: "sale", label: "매매" },
				{ value: "jeonse", label: "전세" },
				{ value: "monthly", label: "월세" },
				{ value: "yearly", label: "년세" }
			];
			dealMenu.innerHTML = renderAdminListingFilterMenu("deal", [{ title: "가격 유형", options: deals, className: "deal-filter-grid broker-home-price-type-grid" }]);
		}
		const areaMenu = document.getElementById("adminListingAreaFilterMenu");
		if (areaMenu) areaMenu.innerHTML = renderAdminListingAreaFilterMenu();
		const landTypeMenu = document.getElementById("adminListingLandTypeFilterMenu");
		if (landTypeMenu) landTypeMenu.innerHTML = renderAdminListingFilterMenu("landType", getBrokerHomeLandTypeSections(), "지목");
		const landUseZoneMenu = document.getElementById("adminListingLandUseZoneFilterMenu");
		if (landUseZoneMenu) landUseZoneMenu.innerHTML = renderAdminListingFilterMenu("landUseZone", getBrokerHomeLandUseZoneSections(), "용도지역");
	}

	function syncAdminListingFilterArrow(type, isOpen)
	{
		const btn = document.getElementById(getAdminListingFilterBtnId(type));
		const icon = btn ? btn.querySelector("i.fa-solid") : null;
		if (!icon) return;
		icon.classList.toggle("fa-chevron-up", !!isOpen);
		icon.classList.toggle("fa-chevron-down", !isOpen);
	}

	function syncAdminListingFilterArrows()
	{
		["property", "deal", "area", "landType", "landUseZone"].forEach((type) => {
			const menu = document.getElementById(getAdminListingFilterMenuId(type));
			syncAdminListingFilterArrow(type, !!(menu && menu.classList.contains("open")));
		});
	}

	function closeAdminListingFilterMenus(exceptType)
	{
		["property", "deal", "area", "landType", "landUseZone"].forEach((type) => {
			if (exceptType && type === exceptType) return;
			const menu = document.getElementById(getAdminListingFilterMenuId(type));
			if (menu) menu.classList.remove("open");
		});
		syncAdminListingFilterArrows();
	}

	function reopenAdminListingFilterMenu(type)
	{
		const normalizedType = type === "area" ? "area" : normalizeAdminListingFilterType(type);
		const menu = document.getElementById(getAdminListingFilterMenuId(normalizedType));
		if (menu) menu.classList.add("open");
		if (normalizedType === "area") syncAdminListingAreaFilterUi();
		syncAdminListingFilterArrows();
	}

	function toggleAdminListingFilterMenu(type)
	{
		const normalizedType = type === "area" ? "area" : normalizeAdminListingFilterType(type);
		const menu = document.getElementById(getAdminListingFilterMenuId(normalizedType));
		if (!menu) return;
		const willOpen = !menu.classList.contains("open");
		closeAdminListingFilterMenus(normalizedType);
		menu.classList.toggle("open", willOpen);
		if (normalizedType === "area") syncAdminListingAreaFilterUi();
		syncAdminListingFilterArrows();
	}

	function syncAdminListingFilterUi()
	{
		const labelGetters = {
			property: (value) => getBrokerHomeSectionOptionLabel(getBrokerHomePropertyTypeSections(), value),
			deal: getBrokerDealLabel,
			landType: (value) => getBrokerHomeSectionOptionLabel(getBrokerHomeLandTypeSections(), value),
			landUseZone: (value) => getBrokerHomeSectionOptionLabel(getBrokerHomeLandUseZoneSections(), value)
		};
		["property", "deal", "area", "landType", "landUseZone"].forEach((type) => {
			const btn = document.getElementById(getAdminListingFilterBtnId(type));
			const isArea = type === "area";
			const values = getAdminListingFilterTargetSet(type);
			const areaRange = isArea ? getAdminListingAreaRange() : null;
			const areaActive = isArea && isAdminListingAreaRangeActive(areaRange);
			const label = isArea
				? (areaActive ? formatAdminListingAreaRangeSummary(areaRange) : getAdminListingFilterFallbackLabel(type))
				: getAdminListingCompactFilterLabel(values, getAdminListingFilterFallbackLabel(type), labelGetters[type], type === "property" ? 3 : 2);
			if (btn) {
				btn.innerHTML = `${escapeAdminHtml(label)} <i class="fa-solid fa-chevron-down" aria-hidden="true"></i>`;
				btn.classList.toggle("active", isArea ? areaActive : values.size > 0);
			}
		});
		document.querySelectorAll(".broker-home-filter-check[data-admin-listing-filter-option]").forEach((input) => {
			const type = input.dataset.adminListingFilterOption;
			const values = getAdminListingFilterTargetSet(type);
			input.checked = values.has(input.dataset.value || "");
			const option = input.closest(".broker-home-filter-option");
			if (option) option.classList.toggle("active", input.checked);
		});
		syncAdminListingAreaFilterUi();
		syncAdminListingFilterArrows();
	}

	function applyAdminListingAdvancedFilters(rows)
	{
		const dealFilter = adminListingDealFilter instanceof Set ? adminListingDealFilter : new Set();
		return (Array.isArray(rows) ? rows : []).filter((row) => {
			if (adminListingPropertyFilter.size && !adminListingPropertyFilter.has(row.property_type)) return false;
			if (!dealFilter.size) return false;
			if (!(Array.isArray(row.deal_types) && row.deal_types.some((deal) => dealFilter.has(deal)))) return false;
			if (!isBrokerListingInAreaFilters(row, new Set(), getAdminListingAreaRange())) return false;
			if (!isBrokerListingInTextFilter(getBrokerListingLandTypeValue(row), adminListingLandTypeFilter)) return false;
			if (!isBrokerListingInTextFilter(getBrokerListingLandUseZoneValue(row), adminListingLandUseZoneFilter)) return false;
			return true;
		});
	}

	function isAdminListingDefaultDealFilter()
	{
		return adminListingDealFilter instanceof Set
			&& adminListingDealFilter.size === ADMIN_LISTING_DEFAULT_DEAL_FILTER_VALUES.length
			&& ADMIN_LISTING_DEFAULT_DEAL_FILTER_VALUES.every((value) => adminListingDealFilter.has(value));
	}

	function isAdminListingServerPagedState()
	{
		return adminListingView === "all"
			&& !getAdminListingSearchQuery()
			&& adminListingPropertyFilter.size === 0
			&& isAdminListingDefaultDealFilter()
			&& !isAdminListingAreaRangeActive(getAdminListingAreaRange())
			&& adminListingLandTypeFilter.size === 0
			&& adminListingLandUseZoneFilter.size === 0;
	}

	function renderCachedAdminListings()
	{
		if (!Array.isArray(adminListingRowsCache)) return false;
		renderAdminListings(adminListingRowsCache, adminListingRowsCacheRenderOptions || {});
		return true;
	}

	function applyAdminListingFilterOptionChange(input)
	{
		if (!input) return;
		const type = normalizeAdminListingFilterType(input.dataset.adminListingFilterOption);
		const value = input.dataset.value || "";
		const targetSet = getAdminListingFilterTargetSet(type);
		if (input.checked) targetSet.add(value);
		else targetSet.delete(value);
		setAdminListingPage(1);
		loadAdminListings();
		reopenAdminListingFilterMenu(type);
	}

	function setAdminListingPage(value)
	{
		const next = Math.floor(Number(value));
		if (!Number.isFinite(next) || next < 1) {
			adminListingPage = 1;
			return;
		}
		adminListingPage = next;
	}

	function getAdminListingPage(totalPages)
	{
		const maxPage = Math.max(1, Number(totalPages) || 1);
		if (!Number.isFinite(adminListingPage) || adminListingPage < 1) adminListingPage = 1;
		if (adminListingPage > maxPage) adminListingPage = maxPage;
		return adminListingPage;
	}

	function renderAdminListingPagination(totalCount, totalPages, currentPage)
	{
		if (totalCount <= ADMIN_LISTINGS_PER_PAGE || totalPages <= 1) return "";
		const items = getBrokerListingPaginationItems(totalPages, currentPage);
		return `
			<nav class="broker-listing-pagination" aria-label="관리자 매물 페이지">
				${items.map((item) => {
					if (item === "ellipsis") return '<span class="broker-listing-page-ellipsis">…</span>';
					const page = Number(item);
					return `<button type="button" class="broker-listing-page-btn ${page === currentPage ? "active" : ""}" data-admin-listing-page="${page}" aria-current="${page === currentPage ? "page" : "false"}">${page}</button>`;
				}).join("")}
			</nav>
		`;
	}

	function scrollAdminListingsToTop()
	{
		const panel = document.getElementById("adminPagePanel");
		if (!panel) return;
		panel.scrollTop = 0;
	}

	function updateAdminListingFilterCounts(rows)
	{
		const list = Array.isArray(rows) ? rows : [];
		const activeRows = getAdminListingActiveRows(list);
		const visibleRows = getAdminListingVisibleRows(list);
		// 4.938: 하단 실제 매물 수도 관리자 `전체`와 같은 행ㆍ같은 상태 판정 결과를 그대로 씁니다.
		realjejuManagementVersionListingCount = visibleRows.length;
		updateRealjejuTopbarVersionText();
		const setText = (id, value) => {
			const el = document.getElementById(id);
			if (el) el.textContent = String(value);
		};
		setText("adminListingsAllCount", visibleRows.length);
		setText("adminListingsReportedCount", activeRows.filter(isAdminListingReported).length);
		setText("adminListingsClosedCount", activeRows.filter((row) => getBrokerListingEffectiveStatus(row) === "closed").length);
		setText("adminListingsHiddenCount", activeRows.filter((row) => ["hidden", "archive"].includes(getBrokerListingEffectiveStatus(row))).length);
		setText("adminListingsDeletedCount", list.filter(isAdminListingDeleted).length);
		document.querySelectorAll("[data-admin-listing-view]").forEach((btn) => {
			btn.classList.toggle("active", btn.dataset.adminListingView === adminListingView);
		});
	}

	function formatAdminListingListAddress(value)
	{
		const text = String(value || "").replace(/\s+/g, " ").trim();
		if (!text) return "-";
		return text.replace(/(\s)(?:산\s*)?\d+(?:-\d+)*(?:번지)?\s*$/u, "$1****");
	}

	function formatManagementListingTitle(value, listingNo)
	{
		const fallback = "제목 없음";
		const title = String(value || fallback).trim() || fallback;
		const normalizedListingNo = String(listingNo || "").trim();
		if (!normalizedListingNo) return title;
		const parenthesizedPrefix = "(" + normalizedListingNo + ")";
		const bracketedPrefix = "[" + normalizedListingNo + "]";
		if (title.startsWith(parenthesizedPrefix)) return title.slice(parenthesizedPrefix.length).trim() || fallback;
		if (title.startsWith(bracketedPrefix)) return title.slice(bracketedPrefix.length).trim() || fallback;
		return title;
	}

	function renderAdminListings(rows, options = {})
	{
		const listEl = document.getElementById("adminListingsList");
		if (!listEl) return;
		const operatorRestricted = document.body.classList.contains("operator-page-open")
			&& !isAdminUser(currentRealjejuAuthUser);
		const list = Array.isArray(rows) ? rows : [];
		const serverPaged = options.serverPaged === true;
		const countRows = Array.isArray(options.countRows) ? options.countRows : list;
		populateAdminListingFilterMenus();
		updateAdminListingFilterCounts(countRows);
		syncAdminListingFilterUi();
		const filteredRows = serverPaged
			? sortListingsByRegistrationDateDesc(list)
			: sortListingsByRegistrationDateDesc(getAdminListingFilteredRows(list));
		const filteredTotalCount = serverPaged
			? Math.max(0, Number(options.totalCount) || 0)
			: filteredRows.length;

		if (!list.length && filteredTotalCount === 0) {
			listEl.classList.remove("broker-listing-list");
			listEl.innerHTML = '<div class="admin-empty">등록된 매물이 없습니다.</div>';
			return;
		}
		if (!filteredRows.length || filteredTotalCount === 0) {
			listEl.classList.remove("broker-listing-list");
			listEl.innerHTML = '<div class="admin-empty">조건에 맞는 매물이 없습니다.</div>';
			return;
		}

		const totalPages = Math.max(1, Math.ceil(filteredTotalCount / ADMIN_LISTINGS_PER_PAGE));
		const currentPage = getAdminListingPage(totalPages);
		const startIndex = (currentPage - 1) * ADMIN_LISTINGS_PER_PAGE;
		const pageRows = serverPaged
			? filteredRows
			: filteredRows.slice(startIndex, startIndex + ADMIN_LISTINGS_PER_PAGE);

		listEl.classList.add("broker-listing-list", "management-list-card-list");
		listEl.innerHTML = `
			<div class="broker-listing-head admin-listing-head">
				<div>사진</div>
				<div>매물유형</div>
				<div>상태</div>
				<div>등록날짜</div>
				<div class="broker-listing-id-views-head"><span>매물번호</span><span>조회</span></div>
				<div>제목</div>
				<div><button type="button" class="broker-listing-area-toggle" data-broker-listing-area-toggle>면적 <i class="fa-solid fa-right-left broker-listing-area-toggle-icon" aria-hidden="true"></i></button></div>
				<div>가격</div>
				<div></div>
				<div></div>
				<div>관리</div>
			</div>
		` + pageRows.map((row) => {
			const createdHtml = formatAdminListingDateTimeHtml(getBrokerListingDisplayDateSource(row));
			const listingNo = getBrokerListingNo(row);
			const viewCount = Math.max(0, Math.trunc(getDetailViewCount(row)));
			const areaText = getBrokerListingAreaValue(row);
			const priceInfo = getBrokerListingDealPrice(row);
			const priceHtml = priceInfo.dealLabel || priceInfo.priceLabel
				? `${priceInfo.dealLabel ? `<span class="broker-listing-price-deal">${escapeAdminHtml(priceInfo.dealLabel)}</span>` : ""}${priceInfo.priceLabel ? `<span class="broker-listing-price-amount">${escapeAdminHtml(priceInfo.priceLabel)}</span>` : ""}`
				: "-";
		const rowId = escapeAdminHtml(row.id);
		const isSelectedRow = normalizeItemId(row.id) === adminSelectedListingId;
		const effectiveStatus = getBrokerListingEffectiveStatus(row);
			const closedAction = effectiveStatus === "closed" ? "published" : "closed";
			const closedLabel = effectiveStatus === "closed" ? "거래중으로 변경" : "거래완료";
			const hiddenAction = ["hidden", "archive"].includes(effectiveStatus) ? "published" : "hidden";
			const hiddenLabel = ["hidden", "archive"].includes(effectiveStatus) ? "숨김해제" : "숨김";
			const listAddress = formatAdminListingListAddress(row.address1 || row.public_address);
			const officeName = getAdminListingOfficeName(row);
			return `
					<div class="broker-listing-row admin-listing-row${isSelectedRow ? " is-selected" : ""}" data-admin-listing-id="${rowId}">
					<div class="broker-listing-cell broker-listing-photo-cell"><div class="broker-listing-thumb">${getBrokerListingThumbHtml(row)}</div></div>
					<div class="broker-listing-cell broker-listing-type" data-mobile-listing-no="${escapeAdminHtml(listingNo)}"><span class="broker-listing-type-label">${escapeAdminHtml(row.property_type_label || "-")}</span><span class="admin-listing-mobile-office">${officeName ? escapeAdminHtml(officeName) : ""}</span></div>
					<div class="broker-listing-cell"><span class="broker-listing-status ${escapeAdminHtml(effectiveStatus || "draft")}">${escapeAdminHtml(getBrokerListingStatusLabel(effectiveStatus))}</span></div>
					<div class="broker-listing-cell broker-listing-meta admin-listing-date-cell">${createdHtml}</div>
					<div class="broker-listing-cell broker-listing-no broker-listing-no-views"><span class="broker-listing-no-value">${escapeAdminHtml(listingNo)}</span><span class="broker-listing-view-value">${viewCount.toLocaleString("ko-KR")}</span></div>
					<div class="broker-listing-title-cell">
						<div class="broker-listing-title">${escapeAdminHtml(formatManagementListingTitle(row.title, listingNo))}</div>
						<div class="broker-listing-address">${escapeAdminHtml(listAddress)}</div>
						${officeName ? `<div class="broker-listing-office">${escapeAdminHtml(officeName)}</div>` : ""}
					</div>
					<div class="broker-listing-cell broker-listing-area">${escapeAdminHtml(areaText)}</div>
					<div class="broker-listing-cell broker-listing-price">${priceHtml}</div>
					<div class="broker-listing-cell"></div>
					<div class="broker-listing-cell"></div>
					<div class="broker-listing-menu-cell">
						${operatorRestricted && effectiveStatus === "deleted" ? "" : `
							<button type="button" class="broker-listing-menu-btn" data-admin-listing-menu="${rowId}" aria-label="매물 관리 메뉴">⋮</button>
							<div class="broker-listing-more-menu" data-admin-listing-menu-panel="${rowId}">
								${operatorRestricted ? `
									<button type="button" class="broker-listing-menu-item" data-admin-listing-action="${closedAction}" data-listing-id="${rowId}">${closedLabel}</button>
									<button type="button" class="broker-listing-menu-item" data-admin-listing-action="${hiddenAction}" data-listing-id="${rowId}">${hiddenLabel}</button>
								` : (effectiveStatus === "deleted" ? `
									<button type="button" class="broker-listing-menu-item" data-admin-listing-action="published" data-listing-id="${rowId}">복원</button>
									<button type="button" class="broker-listing-menu-item danger" data-admin-listing-action="permanent_delete" data-listing-id="${rowId}">영구삭제</button>
								` : `
									<button type="button" class="broker-listing-menu-item" data-admin-listing-action="refresh" data-listing-id="${rowId}">현재날짜로 갱신</button>
									<button type="button" class="broker-listing-menu-item" data-admin-listing-action="${closedAction}" data-listing-id="${rowId}">${closedLabel}</button>
									<button type="button" class="broker-listing-menu-item" data-admin-listing-action="${hiddenAction}" data-listing-id="${rowId}">${hiddenLabel}</button>
									<button type="button" class="broker-listing-menu-item danger" data-admin-listing-action="delete" data-listing-id="${rowId}">삭제</button>
								`)}
							</div>
						`}
					</div>
				</div>
			`;
		}).join("") + renderAdminListingPagination(filteredTotalCount, totalPages, currentPage);
		}

		function syncAdminListingSelectedRows()
		{
			document.querySelectorAll(".admin-listing-row[data-admin-listing-id]").forEach((rowEl) => {
				const listingId = normalizeItemId(rowEl.dataset.adminListingId);
				rowEl.classList.toggle("is-selected", !!adminSelectedListingId && listingId === adminSelectedListingId);
			});
		}

		function setAdminListingSelectedId(listingId)
		{
			adminSelectedListingId = normalizeItemId(listingId);
			syncAdminListingSelectedRows();
		}

		window.realjejuSetAdminListingSelectedId = setAdminListingSelectedId;

		function clearAdminListingSelectedId()
		{
			if (!adminSelectedListingId) return;
			adminSelectedListingId = "";
			syncAdminListingSelectedRows();
		}

		window.realjejuClearAdminListingSelectedId = clearAdminListingSelectedId;

