	const ADMIN_LISTING_QUERY_PAGE_SIZE = 1000;

	function normalizeAdminListingSummaryRow(row)
	{
		const source = row && typeof row === "object" ? row : {};
		const summary = { ...source };
		Object.keys(summary).forEach((key) => {
			if (key.startsWith("payload_")) delete summary[key];
		});
		const officeName = String(source.payload_registrant_office_name || "").trim();
		const photoCount = parseListingPhotoCountValue(source.payload_photo_count ?? source.payload_photo_count_camel);
		const payload = {
			thumbnail_url: source.payload_thumbnail_url || "",
			thumbnail: source.payload_thumbnail && typeof source.payload_thumbnail === "object" ? source.payload_thumbnail : {},
			prices: source.payload_prices && typeof source.payload_prices === "object" ? source.payload_prices : {},
			areas: source.payload_areas && typeof source.payload_areas === "object" ? source.payload_areas : {},
			registrant: officeName ? { office_name: officeName } : {},
			office_name: source.payload_office_name || "",
			last_relisted_at: source.payload_last_relisted_at || null,
			broker_status: source.payload_broker_status || null,
			deleted_at: source.payload_deleted_at || null,
			reported: source.payload_reported,
			is_reported: source.payload_is_reported,
			report_count: source.payload_report_count,
			reports_count: source.payload_reports_count,
			reported_at: source.payload_reported_at || null,
			last_reported_at: source.payload_last_reported_at || null,
			listing_no: source.payload_listing_no || "",
			listingNo: source.payload_listing_no_camel || "",
			property_listing_no: source.payload_property_listing_no || "",
			memo: source.payload_memo || "",
			broker_memo: source.payload_broker_memo || "",
			detail_address: source.payload_detail_address || "",
			description: source.payload_description || "",
			land_type: source.payload_land_type || "",
			land_use_zone: source.payload_land_use_zone || "",
			photo_count: photoCount,
			photoCount: photoCount
		};
		return {
			...summary,
			thumbnail_url: payload.thumbnail_url,
			photo_count: photoCount,
			payload
		};
	}

	async function fetchAdminListingRowsInPages(client, selectColumns)
	{
		const rows = [];
		for (let from = 0; ; from += ADMIN_LISTING_QUERY_PAGE_SIZE) {
			const result = await client
				.from("property_listings")
				.select(selectColumns)
				.order("created_at", { ascending: false })
				.order("id", { ascending: false })
				.range(from, from + ADMIN_LISTING_QUERY_PAGE_SIZE - 1);
			if (result.error) return result;
			const pageRows = Array.isArray(result.data) ? result.data : [];
			rows.push(...pageRows);
			if (pageRows.length < ADMIN_LISTING_QUERY_PAGE_SIZE) {
				return { ...result, data: rows, error: null };
			}
		}
	}

	async function fetchAdminPropertyListings(client)
	{
		const result = await fetchAdminListingRowsInPages(client, ADMIN_LISTING_SUMMARY_SELECT);
		return {
			...result,
			data: !result.error && Array.isArray(result.data)
				? result.data.map(normalizeAdminListingSummaryRow)
				: result.data
		};
	}

	async function fetchAdminListingMetadata(client)
	{
		const result = await fetchAdminListingRowsInPages(client, ADMIN_LISTING_META_SELECT);
		return {
			...result,
			data: !result.error && Array.isArray(result.data)
				? result.data.map(normalizeAdminListingSummaryRow)
				: result.data
		};
	}

	async function fetchAdminPropertyListingsByIds(client, listingIds)
	{
		const orderedIds = (Array.isArray(listingIds) ? listingIds : [])
			.map(normalizeItemId)
			.filter(Boolean);
		if (!orderedIds.length) return { data: [], error: null };
		const result = await client
			.from("property_listings")
			.select(ADMIN_LISTING_SUMMARY_SELECT)
			.in("id", orderedIds);
		if (result.error || !Array.isArray(result.data)) return result;
		const normalizedRows = result.data.map(normalizeAdminListingSummaryRow);
		const rowsById = new Map(normalizedRows.map(row => [normalizeItemId(row?.id), row]));
		return {
			...result,
			data: orderedIds.map(id => rowsById.get(id)).filter(Boolean)
		};
	}

	async function loadAdminListings(options = {})
	{
		const listEl = document.getElementById("adminListingsList");
		if (!listEl) return;
		if (!isAdminUser(currentRealjejuAuthUser) && !isOperatorUser(currentRealjejuAuthUser)) {
			listEl.classList.remove("broker-listing-list");
			listEl.innerHTML = '<div class="admin-empty">관리자 또는 운영자 계정에서만 이용 가능합니다.</div>';
			return;
		}
		const client = getRealjejuSupabaseClient();
		if (!client) {
			listEl.classList.remove("broker-listing-list");
			listEl.innerHTML = '<div class="admin-empty">Supabase 연결 설정을 확인하세요.</div>';
			return;
		}

		if (options.force === true) clearAdminListingRowsCache();
		const serverPaged = isAdminListingServerPagedState();
		const requestKey = serverPaged ? `paged:${adminListingPage}` : "full";
		const hasMatchingCache = Array.isArray(adminListingRowsCache)
			&& ((serverPaged && adminListingRowsCacheMode === "paged" && adminListingRowsCachePage === adminListingPage)
				|| (!serverPaged && adminListingRowsCacheMode === "full"));
		if (hasMatchingCache) {
			renderCachedAdminListings();
			return;
		}

		if (adminListingLoadPromise && adminListingLoadRequestKey === requestKey) return adminListingLoadPromise;

		if (!options.silent && !listEl.querySelector(".admin-listing-row")) {
			listEl.classList.remove("broker-listing-list");
			listEl.innerHTML = '<div class="admin-empty">매물을 불러오는 중입니다.</div>';
		}

		listEl.setAttribute("aria-busy", "true");
		const requestSequence = ++adminListingLoadSequence;
		adminListingLoadRequestKey = requestKey;
		let requestPromise = null;
		requestPromise = (async () => {
			void purgeAdminExpiredTrashIfNeeded(client);
			if (serverPaged) {
				if (!Array.isArray(adminListingMetaRowsCache)) {
					const metaResult = await fetchAdminListingMetadata(client);
					if (metaResult.error) throw metaResult.error;
					adminListingMetaRowsCache = Array.isArray(metaResult.data) ? metaResult.data : [];
				}
				if (requestSequence !== adminListingLoadSequence) return;
				const eligibleRows = sortListingsByRegistrationDateDesc(getAdminListingFilteredRows(adminListingMetaRowsCache));
				const totalCount = eligibleRows.length;
				const totalPages = Math.max(1, Math.ceil(totalCount / ADMIN_LISTINGS_PER_PAGE));
				const currentPage = getAdminListingPage(totalPages);
				const startIndex = (currentPage - 1) * ADMIN_LISTINGS_PER_PAGE;
				const pageIds = eligibleRows
					.slice(startIndex, startIndex + ADMIN_LISTINGS_PER_PAGE)
					.map(row => row?.id);
				const pageResult = await fetchAdminPropertyListingsByIds(client, pageIds);
				if (pageResult.error) throw pageResult.error;
				const pageRows = await hydrateListingRowsWithLegacyThumbnails(client, Array.isArray(pageResult.data) ? pageResult.data : []);
				const adminViewCounts = pageRows.length
					? await fetchViewCounts(pageRows, { force: true })
					: {};
				if (requestSequence !== adminListingLoadSequence) return;
				viewMap = { ...viewMap, ...adminViewCounts };
				adminListingRowsCache = pageRows;
				adminListingRowsCacheMode = "paged";
				adminListingRowsCachePage = currentPage;
				adminListingRowsCacheRenderOptions = {
					serverPaged: true,
					totalCount,
					countRows: adminListingMetaRowsCache
				};
				renderCachedAdminListings();
				return;
			}

			const { data, error } = await fetchAdminPropertyListings(client);

			if (error) throw error;

			const fullRows = await hydrateListingRowsWithLegacyThumbnails(client, Array.isArray(data) ? data : []);
			const adminViewCounts = await fetchViewCounts(fullRows, { force: true });
			if (requestSequence !== adminListingLoadSequence) return;
			viewMap = { ...viewMap, ...adminViewCounts };
			adminListingRowsCache = fullRows;
			adminListingRowsCacheMode = "full";
			adminListingRowsCachePage = 0;
			adminListingRowsCacheRenderOptions = null;
			renderCachedAdminListings();
		})().catch((err) => {
			if (requestSequence !== adminListingLoadSequence) return;
			console.error("관리자 매물 목록 오류:", err);
			listEl.classList.remove("broker-listing-list");
			listEl.innerHTML = `<div class="admin-empty">매물을 불러오지 못했습니다. ${getAdminListingToolsSchemaHelp()}</div>`;
		}).finally(() => {
			if (adminListingLoadPromise === requestPromise) {
				listEl.removeAttribute("aria-busy");
				adminListingLoadPromise = null;
				adminListingLoadRequestKey = "";
			}
		});
		adminListingLoadPromise = requestPromise;
		return requestPromise;
	}

	function formatBrokerManwon(value)
	{
		const num = Number(value);
		if (!Number.isFinite(num) || num <= 0) return "";
		const manwon = Math.round(num);
		const eok = Math.floor(manwon / 10000);
		const rest = manwon % 10000;
		if (eok > 0 && rest > 0) return `${eok.toLocaleString("ko-KR")}억 ${rest.toLocaleString("ko-KR")}만원`;
		if (eok > 0) return `${eok.toLocaleString("ko-KR")}억`;
		return `${manwon.toLocaleString("ko-KR")}만원`;
	}

	function getBrokerDealLabel(deal)
	{
		const labels = { sale: "매매", jeonse: "전세", monthly: "월세", yearly: "년세", short: "단기" };
		return labels[deal] || deal || "-";
	}

	function getBrokerListingPrice(row)
	{
		const payload = row && row.payload && typeof row.payload === "object" ? row.payload : {};
		const prices = payload.prices || {};
		const deals = Array.isArray(row.deal_types) ? row.deal_types : [];
		// 거래유형은 별도 컬럼에 표시하므로 가격 칸에는 금액만 둔다.
		if (deals.includes("sale") && prices.sale?.price) return formatBrokerManwon(prices.sale.price);
		if (deals.includes("jeonse") && prices.jeonse?.deposit) return formatBrokerManwon(prices.jeonse.deposit);
		if (deals.includes("monthly")) {
			const deposit = formatBrokerManwon(prices.monthly?.deposit);
			const rent = formatBrokerManwon(prices.monthly?.rent);
			const price = [deposit, rent].filter(Boolean).join(" / ");
			return price || "-";
		}
		if (deals.includes("yearly")) {
			const deposit = formatBrokerManwon(prices.yearly?.deposit);
			const rent = formatBrokerManwon(prices.yearly?.rent);
			const price = [deposit, rent].filter(Boolean).join(" / ");
			return price || "-";
		}
		if (deals.includes("short")) {
			const deposit = formatBrokerManwon(prices.short?.deposit);
			const rent = formatBrokerManwon(prices.short?.rent);
			const price = [deposit, rent].filter(Boolean).join(" / ");
			return price || "-";
		}
		return "-";
	}

	function getBrokerListingDealPrice(row)
	{
		const deals = Array.isArray(row?.deal_types) ? row.deal_types : [];
		const dealLabel = deals.length ? deals.map(getBrokerDealLabel).filter(Boolean).join(" · ") : "";
		const price = getBrokerListingPrice(row);
		return {
			dealLabel: dealLabel || "",
			priceLabel: price && price !== "-" ? price : ""
		};
	}

	function getBrokerListingThumbHtml(row)
	{
		const photos = Array.isArray(row.photos) ? row.photos : [];
		const payload = row && row.payload && typeof row.payload === "object" ? row.payload : {};
		const url = getListingSummaryThumbnailUrl(row, payload, photos);
		return url
			? `<img src="${escapeAdminHtml(url)}" alt="매물 사진" loading="lazy" decoding="async">`
			: `<span>사진 없음</span>`;
	}

	// 중개사 홈 목록용 등록일/매물번호/블로그 복사 문구를 한곳에서 만든다
	function formatBrokerListingDate(value)
	{
		if (!value) return "-";
		const date = new Date(value);
		if (Number.isNaN(date.getTime())) return "-";
		const yy = String(date.getFullYear()).slice(2);
		const mm = String(date.getMonth() + 1).padStart(2, "0");
		const dd = String(date.getDate()).padStart(2, "0");
		return `${yy}.${mm}.${dd}`;
	}

	function getBrokerListingDisplayDateSource(row)
	{
		const payload = row && row.payload && typeof row.payload === "object" ? row.payload : {};
		const candidates = [
			row?.updated_at,
			payload.last_relisted_at,
			row?.created_at
		].filter(Boolean);
		let latestValue = "";
		let latestTimestamp = Number.NEGATIVE_INFINITY;
		candidates.forEach((value) =>
		{
			const timestamp = new Date(value).getTime();
			if (!Number.isFinite(timestamp) || timestamp <= latestTimestamp) return;
			latestTimestamp = timestamp;
			latestValue = value;
		});
		return latestValue || row?.updated_at || payload.last_relisted_at || row?.created_at || "";
	}

	function formatAdminListingDateTimeHtml(value)
	{
		if (!value) return "-";
		const date = new Date(value);
		if (Number.isNaN(date.getTime())) return "-";
		const yy = String(date.getFullYear()).slice(2);
		const mm = String(date.getMonth() + 1).padStart(2, "0");
		const dd = String(date.getDate()).padStart(2, "0");
		const hh = String(date.getHours()).padStart(2, "0");
		const mi = String(date.getMinutes()).padStart(2, "0");
		const ss = String(date.getSeconds()).padStart(2, "0");
		return `<span class="admin-listing-date-stack"><span class="admin-listing-date-day">${yy}.${mm}.${dd}</span><span class="admin-listing-date-time">${hh}:${mi}:${ss}</span></span>`;
	}

	function getAdminListingOfficeName(row)
	{
		const payload = row && row.payload && typeof row.payload === "object" ? row.payload : {};
		const registrant = payload.registrant && typeof payload.registrant === "object" ? payload.registrant : {};
		return String(
			registrant.office_name
			|| payload.office_name
			|| row?.office_name
			|| ""
		).trim();
	}

	// 매물관리 등록날짜 칸은 일반 수정일ㆍ재등록 갱신일ㆍ최초 등록일 중 가장 최근 시각을 표시한다.

	// 현재날짜 갱신 사용건수는 payload 안에 날짜별로 누적해 오늘치만 합산한다
	function getBrokerRelistUsageDateKey(value = new Date())
	{
		const date = value instanceof Date ? value : new Date(value);
		if (Number.isNaN(date.getTime())) return "";
		const yyyy = String(date.getFullYear());
		const mm = String(date.getMonth() + 1).padStart(2, "0");
		const dd = String(date.getDate()).padStart(2, "0");
		return `${yyyy}-${mm}-${dd}`;
	}

	function getBrokerListingRelistUsageCount(row, dateKey = getBrokerRelistUsageDateKey())
	{
		const payload = row && row.payload && typeof row.payload === "object" ? row.payload : {};
		const counts = payload.relist_usage_by_date && typeof payload.relist_usage_by_date === "object" ? payload.relist_usage_by_date : {};
		const count = Number(counts[dateKey]);
		return Number.isFinite(count) && count > 0 ? count : 0;
	}

		const BROKER_RELIST_DAILY_LIMIT = 0;

		function getBrokerRelistDailyLimit()
		{
			const limits = typeof window.realjejuGetActivePaymentLimits === "function" ? window.realjejuGetActivePaymentLimits() : null;
			const relistLimit = Number(limits?.relist);
			return Number.isFinite(relistLimit) ? relistLimit : BROKER_RELIST_DAILY_LIMIT;
		}

	function getBrokerRelistUsageTotal(rows, dateKey = getBrokerRelistUsageDateKey())
	{
		const rowCount = (Array.isArray(rows) ? rows : []).reduce((total, row) => total + getBrokerListingRelistUsageCount(row, dateKey), 0);
		const state = typeof window.realjejuGetCurrentPaymentPlanState === "function" ? window.realjejuGetCurrentPaymentPlanState() : null;
		const persistedCount = normalizeRealjejuNonnegativeCount(state?.usage?.relist);
		return Math.max(rowCount, persistedCount);
	}

	function getBrokerRelistQuotaExhaustedMessage(usedCount, dailyLimit)
	{
		const used = Math.max(0, Math.trunc(Number(usedCount) || 0));
		const limit = Math.max(0, Math.trunc(Number(dailyLimit) || 0));
		return `하루 재등록 사용건수를 모두 사용했습니다.\n오늘 사용건수: ${used} / ${limit}건`;
	}

	function getBrokerListingStatusLabel(status)
	{
		if (status === "published") return "등록";
		if (status === "draft") return "임시";
		if (status === "closed") return "거래완료";
		if (status === "hidden") return "숨김";
		if (status === "archive") return "보관";
		if (status === "deleted" || status === "trash") return "휴지통";
		return status || "-";
	}

	// DB status 제약을 건드리지 않고 거래완료 상태는 payload 관리상태로 판별한다
	function getBrokerListingEffectiveStatus(row)
	{
		const payload = row && row.payload && typeof row.payload === "object" ? row.payload : {};
		const status = String(row && row.status ? row.status : "").trim().toLowerCase();
		if (status === "deleted" || status === "trash" || payload.deleted_at) return "deleted";
		if (payload.broker_status === "closed") return "closed";
		if (payload.broker_status === "hidden" || payload.broker_status === "archive") return "hidden";
		return status;
	}

	function getBrokerListingNo(row)
	{
		const payload = row && row.payload && typeof row.payload === "object" ? row.payload : {};
		const storedNo = getPayloadListingNoCandidate(payload) || normalizePropertyListingNoCandidate(row?.listing_no || "");
		if (storedNo) return storedNo;
		const source = [
			row?.title,
			payload.description
		].filter(Boolean).join("\n");
		const extractedNo = extractPropertyListingNoCandidate(source);
		if (extractedNo) return extractedNo;
		return String(row?.id || "").slice(0, 8) || "-";
	}

	function getBrokerListingAgencyMemo(row)
	{
		const payload = row && row.payload && typeof row.payload === "object" ? row.payload : {};
		return String(payload.agency_memo || "").trim();
	}

	function renderBrokerListingAgencyMemo(row)
	{
		const memo = getBrokerListingAgencyMemo(row);
		if (!memo) return "";
		const html = escapeAdminHtml(memo).replace(/\r\n|\r|\n/g, "<br>");
		return `
			<div class="broker-listing-private-memo">
				<button type="button" class="broker-listing-memo-trigger" aria-label="중개사무소 메모 보기">(메모)</button>
				<span class="broker-listing-memo-tooltip" role="tooltip">${html}</span>
			</div>
		`;
	}

