	function renderBrokerHomeListingFlagText(row)
	{
		const flags = getBrokerListingFlags(row);
		const labels = [];
		if (flags.exclusive) labels.push("전속");
		if (flags.coBroker) labels.push("공동");
		return labels.map((label) => `<span class="broker-listing-flag-badge broker-home-listing-flag-badge">${escapeAdminHtml(label)}</span>`).join("");
	}

	function getBrokerListingAreaUnit()
	{
		return window.realjejuBrokerListingAreaUnit === "py" ? "py" : "m2";
	}

	function formatBrokerListingAreaValue(value)
	{
		const num = Number(value);
		if (!Number.isFinite(num) || num <= 0) return "";
		if (getBrokerListingAreaUnit() === "py") {
			return `${(num / 3.305785).toLocaleString("ko-KR", { maximumFractionDigits: 2 })}평`;
		}
		return `${num.toLocaleString("ko-KR", { maximumFractionDigits: 2 })}㎡`;
	}

	function getBrokerListingAreaValue(row)
	{
		const payload = row && row.payload && typeof row.payload === "object" ? row.payload : {};
		const areas = payload.areas || {};
		const value = areas.exclusive_m2 || areas.total_m2 || areas.building_m2 || areas.land_m2 || areas.supply_m2;
		return formatBrokerListingAreaValue(value) || "-";
	}

	function syncBrokerListingAreaCells()
	{
		document.querySelectorAll(".broker-listing-row[data-listing-id]").forEach((rowEl) => {
			const listingId = rowEl.getAttribute("data-listing-id") || "";
			const row = window.realjejuBrokerListingRowsById?.get(String(listingId));
			const areaEl = rowEl.querySelector(".broker-listing-area");
			if (!row || !areaEl) return;
			areaEl.textContent = getBrokerListingAreaValue(row);
		});
	}

	function syncAdminListingAreaCells()
	{
		document.querySelectorAll(".admin-listing-row[data-admin-listing-id]").forEach((rowEl) => {
			const listingId = rowEl.getAttribute("data-admin-listing-id") || "";
			const row = Array.isArray(adminListingRowsCache)
				? adminListingRowsCache.find((item) => String(item?.id || "") === String(listingId))
				: null;
			const areaEl = rowEl.querySelector(".broker-listing-area");
			if (!row || !areaEl) return;
			areaEl.textContent = getBrokerListingAreaValue(row);
		});
	}

	function getBrokerListingBlogText(row)
	{
		const payload = row && row.payload && typeof row.payload === "object" ? row.payload : {};
		const deals = Array.isArray(row.deal_types) && row.deal_types.length ? row.deal_types.map(getBrokerDealLabel).join(", ") : "";
		return [
			row.title || "",
			`매물유형: ${row.property_type_label || "-"}`,
			deals ? `거래유형: ${deals}` : "",
			`가격: ${getBrokerListingPrice(row)}만원`,
			`주소: ${row.address1 || row.public_address || "-"}`,
			"",
			payload.description || ""
		].filter((line, index) => index === 5 || String(line || "").trim()).join("\n");
	}

	async function copyBrokerListingBlogText(listingId)
	{
		const row = window.realjejuBrokerListingRowsById?.get(String(listingId || ""));
		if (!row) return;
		const text = getBrokerListingBlogText(row);
		try {
			await navigator.clipboard.writeText(text);
			openAuthErrorModal("블로그용 문구를 복사했습니다.", "블로그복사", null);
		}
		catch (err) {
			console.warn("블로그 문구 복사 실패:", err);
			openAuthErrorModal("복사에 실패했습니다. 브라우저 권한을 확인하세요.", "블로그복사", null);
		}
	}

	// 삭제는 즉시 DB 삭제하지 않고 휴지통으로 이동하며, 영구삭제만 실제 삭제한다
	function clearBrokerListingMenuPosition(menu)
	{
		if (!menu) return;
		menu.style.removeProperty("--rj-broker-listing-menu-top");
		menu.style.removeProperty("--rj-broker-listing-menu-left");
		menu.style.removeProperty("visibility");
	}

	function closeBrokerListingMenus(exceptId)
	{
		document.querySelectorAll("[data-broker-listing-menu-panel].open").forEach((menu) => {
			const menuId = menu.getAttribute("data-broker-listing-menu-panel");
			if (exceptId && menuId === String(exceptId)) return;
			menu.classList.remove("open");
			clearBrokerListingMenuPosition(menu);
		});
	}

	function openBrokerListingMenuAtButton(menu, button)
	{
		if (!menu || !button) return;
		const viewportGap = 8;
		const menuGap = 6;
		clearBrokerListingMenuPosition(menu);
		menu.style.visibility = "hidden";
		menu.classList.add("open");

		const buttonRect = button.getBoundingClientRect();
		const menuWidth = menu.offsetWidth || 154;
		const menuHeight = menu.offsetHeight || 0;
		const maxLeft = Math.max(viewportGap, window.innerWidth - menuWidth - viewportGap);
		let left = buttonRect.right - menuWidth;
		left = Math.max(viewportGap, Math.min(left, maxLeft));

		let top = buttonRect.bottom + menuGap;
		if (top + menuHeight > window.innerHeight - viewportGap) {
			top = buttonRect.top - menuHeight - menuGap;
		}
		top = Math.max(viewportGap, Math.min(top, window.innerHeight - menuHeight - viewportGap));

		menu.style.setProperty("--rj-broker-listing-menu-left", `${Math.round(left)}px`);
		menu.style.setProperty("--rj-broker-listing-menu-top", `${Math.round(top)}px`);
		menu.style.removeProperty("visibility");
	}

	function shouldUseAdminListingDirectFallback(error)
	{
		const text = [
			error?.code,
			error?.message,
			error?.details,
			error?.hint
		].filter(Boolean).join(" ");
		return /PGRST202|schema cache|admin_update_property_listing|invalid listing action|23514|check constraint|property_listings_status_check/i.test(text);
	}

	async function fetchAdminListingFullPayload(client, listingId)
	{
		const { data, error } = await client
			.from("property_listings")
			.select("payload")
			.eq("id", listingId)
			.maybeSingle();
		if (error) throw error;
		if (!data) throw new Error("listing not found");
		return data.payload && typeof data.payload === "object" ? { ...data.payload } : {};
	}

	async function updateAdminListingRowActionDirect(client, listingId, action)
	{
		const id = String(listingId || "").trim();
		const nextAction = String(action || "").trim();
		if (!client || !id || !nextAction) return;
		const nowIso = new Date().toISOString();

		if (nextAction === "permanent_delete") {
			await client.from("favorite_listings").delete().eq("listing_id", id);
			const { error } = await client.from("property_listings").delete().eq("id", id);
			if (error) throw error;
			return;
		}

		const payload = await fetchAdminListingFullPayload(client, id);
		if (nextAction === "refresh") {
			const { error } = await client
				.from("property_listings")
				.update({ updated_at: nowIso, payload: { ...payload, last_relisted_at: nowIso } })
				.eq("id", id);
			if (error) throw error;
			return;
		}

		const update = { updated_at: nowIso };

		if (nextAction === "published") {
			update.status = "published";
			delete payload.broker_status;
			delete payload.deleted_at;
			update.payload = payload;
		}
		else if (nextAction === "closed") {
			update.status = "published";
			delete payload.deleted_at;
			update.payload = { ...payload, broker_status: "closed" };
		}
		else if (nextAction === "hidden") {
			update.status = "published";
			delete payload.deleted_at;
			update.payload = { ...payload, broker_status: "hidden" };
		}
		else if (nextAction === "delete") {
			delete payload.broker_status;
			update.status = "deleted";
			update.payload = { ...payload, deleted_at: nowIso };
			let result = await client
				.from("property_listings")
				.update(update)
				.eq("id", id);
			if (result.error && /23514|check constraint|property_listings_status_check/i.test(String([result.error.code, result.error.message, result.error.details, result.error.hint].filter(Boolean).join(" ")))) {
				result = await client
					.from("property_listings")
					.update({ updated_at: nowIso, status: "published", payload: update.payload })
					.eq("id", id);
			}
			if (result.error) throw result.error;
			return;
		}
		else {
			throw new Error("invalid listing action");
		}

		const { error } = await client
			.from("property_listings")
			.update(update)
			.eq("id", id);
		if (error) throw error;
	}

	async function updateAdminListingRowAction(listingId, action)
	{
		const id = String(listingId || "").trim();
		const nextAction = String(action || "").trim();
		if (!id || !nextAction) return;
		const adminAllowed = isAdminUser(currentRealjejuAuthUser);
		const operatorAllowed = !adminAllowed && isOperatorUser(currentRealjejuAuthUser);
		if (!adminAllowed && !operatorAllowed) {
			openAuthErrorModal("관리자 또는 운영자 계정에서만 처리할 수 있습니다.", "매물 관리", null);
			return;
		}
		if (operatorAllowed && !["closed", "hidden", "published"].includes(nextAction)) {
			openAuthErrorModal("운영자는 거래완료와 숨김 상태만 변경할 수 있습니다.", "매물 관리", null);
			return;
		}
		const client = getRealjejuSupabaseClient();
		if (!client) {
			openAuthErrorModal("Supabase 연결 설정을 확인하세요.", "매물 관리", null);
			return;
		}

		try {
			const rpcName = operatorAllowed
				? "operator_update_property_listing_status"
				: "admin_update_property_listing";
			const { error } = await client.rpc(rpcName, {
				p_listing_id: id,
				p_action: nextAction
			});
			if (error) throw error;

			await loadAdminListings({ force: true, silent: true });
			if (typeof window.realjejuReloadMapListings === "function") window.realjejuReloadMapListings();
		}
		catch (err) {
			if (adminAllowed && shouldUseAdminListingDirectFallback(err)) {
				try {
					await updateAdminListingRowActionDirect(client, id, nextAction);
					await loadAdminListings({ force: true, silent: true });
					if (typeof window.realjejuReloadMapListings === "function") window.realjejuReloadMapListings();
					return;
				}
				catch (fallbackErr) {
					console.error("관리자 매물 직접 처리 실패:", fallbackErr);
				}
			}
			console.error("관리자 매물 관리 실패:", err);
			const schemaHelp = operatorAllowed
				? "sql/operator_member_listing_permissions_5.139.sql을 Supabase SQL Editor에서 실행한 뒤 다시 시도하세요."
				: getAdminListingToolsSchemaHelp();
			openAuthErrorModal(`매물 처리에 실패했습니다${formatAdminRpcError(err)}. ${schemaHelp}`, "매물 관리", null);
		}
	}

	async function updateBrokerListingRowAction(listingId, action)
	{
		const id = String(listingId || "").trim();
		let nextAction = String(action || "").trim();
		if (!id || !nextAction) return;
		const user = currentRealjejuAuthUser;
		const client = getRealjejuSupabaseClient();
		if (!user || !user.id || !client) {
			openAuthErrorModal("로그인과 Supabase 연결 상태를 확인하세요.", "중개사 홈", null);
			return;
		}

		try {
			const nowIso = new Date().toISOString();
			if (nextAction === "permanent_delete") {
				const { error } = await client
					.from("property_listings")
					.delete()
					.eq("id", id)
					.eq("user_id", user.id);
				if (error) throw error;
			}
			else {
				const update = { updated_at: nowIso };
				const row = window.realjejuBrokerListingRowsById?.get(id);
				const payload = row && row.payload && typeof row.payload === "object" ? { ...row.payload } : {};
				const currentStatus = getBrokerListingEffectiveStatus(row);
				if (nextAction === "closed" && ["closed", "hidden", "archive"].includes(currentStatus)) {
					nextAction = "published";
					}

					if (nextAction === "refresh") {
						const guardPaymentPlan = getRealjejuPaymentPlanGuard();
						if (guardPaymentPlan && !guardPaymentPlan("중개사 홈")) return;
						const todayKey = getBrokerRelistUsageDateKey();
						const currentRows = Array.from(window.realjejuBrokerListingRowsById?.values?.() || []);
						const dailyLimit = getBrokerRelistDailyLimit();
					const usedCount = getBrokerRelistUsageTotal(currentRows, todayKey);
					if (usedCount >= dailyLimit) {
						openAuthErrorModal(getBrokerRelistQuotaExhaustedMessage(usedCount, dailyLimit), "중개사 홈", null);
						return;
					}
					const relistCounts = payload.relist_usage_by_date && typeof payload.relist_usage_by_date === "object" ? { ...payload.relist_usage_by_date } : {};
					const todayCount = Number(relistCounts[todayKey]);
					relistCounts[todayKey] = (Number.isFinite(todayCount) && todayCount > 0 ? todayCount : 0) + 1;
					// 갱신 버튼을 누른 횟수를 날짜별 사용건수로 보존한다
					update.payload = { ...payload, relist_usage_by_date: relistCounts, last_relisted_at: nowIso };
				}
				if (nextAction === "closed") {
					update.status = "published";
					update.payload = { ...payload, broker_status: "closed" };
				}
				if (nextAction === "hidden") {
					update.status = "published";
					if (payload.deleted_at) delete payload.deleted_at;
					update.payload = { ...payload, broker_status: "hidden" };
				}
				if (nextAction === "delete") {
					update.status = "deleted";
					if (payload.broker_status) delete payload.broker_status;
					update.payload = { ...payload, deleted_at: nowIso };
				}
				if (nextAction === "published") {
					update.status = "published";
					if (payload.broker_status) {
						delete payload.broker_status;
					}
					if (payload.deleted_at) delete payload.deleted_at;
					update.payload = payload;
				}
				const { error } = await client
					.from("property_listings")
					.update(update)
					.eq("id", id)
					.eq("user_id", user.id);
				if (error) throw error;
			}

				clearBrokerListingRowsCache();
				await loadBrokerListings({ force: true });
				if (nextAction === "refresh" && typeof window.realjejuReloadMapListings === "function") window.realjejuReloadMapListings();
			}
			catch (err) {
				console.error("중개사 홈 매물 관리 실패:", err);
				openAuthErrorModal("매물 처리에 실패했습니다.", "중개사 홈", null);
			}
		}

		function getBrokerBulkRefreshQuotaState()
		{
			const rows = Array.from(window.realjejuBrokerListingRowsById?.values?.() || []);
			const todayKey = getBrokerRelistUsageDateKey();
			const dailyLimit = getBrokerRelistDailyLimit();
			const usedCount = getBrokerRelistUsageTotal(rows, todayKey);
			return {
				rows,
				todayKey,
				dailyLimit,
				usedCount,
				remainingCount: Math.max(0, dailyLimit - usedCount)
			};
		}

		async function refreshAllBrokerListingsByDailyLimit()
		{
			if (window.realjejuBrokerBulkRefreshBusy) return;
			const user = currentRealjejuAuthUser;
			const client = getRealjejuSupabaseClient();
			if (!user || !user.id || !client) {
				openAuthErrorModal("로그인과 Supabase 연결 상태를 확인하세요.", "중개사 홈", null);
				return;
			}
			const guardPaymentPlan = getRealjejuPaymentPlanGuard();
			if (guardPaymentPlan && !guardPaymentPlan("전체갱신")) return;

			const quotaState = getBrokerBulkRefreshQuotaState();
			const { rows, todayKey, dailyLimit, usedCount, remainingCount } = quotaState;
			const candidates = rows
				.filter((row) => isBrokerListingInStatusFilter(row, "trading"))
				.sort((a, b) => {
					const aTime = Date.parse(a?.updated_at || a?.created_at || "") || 0;
					const bTime = Date.parse(b?.updated_at || b?.created_at || "") || 0;
					return aTime - bTime;
				});
			if (!candidates.length) {
				openAuthErrorModal("갱신할 거래중 매물이 없습니다.", "전체갱신", null);
				return;
			}

			if (remainingCount <= 0) {
				openAuthErrorModal(getBrokerRelistQuotaExhaustedMessage(usedCount, dailyLimit), "전체갱신", null);
				return;
			}

			const refreshRows = candidates.slice(0, remainingCount);
			const button = document.getElementById("brokerBulkRefreshBtn");
			window.realjejuBrokerBulkRefreshBusy = true;
			if (button) button.disabled = true;
			let successCount = 0;
			try {
				for (const row of refreshRows) {
					const rowId = String(row?.id || "").trim();
					if (!rowId) continue;
					const nowIso = new Date().toISOString();
					const payload = row && row.payload && typeof row.payload === "object" ? { ...row.payload } : {};
					const relistCounts = payload.relist_usage_by_date && typeof payload.relist_usage_by_date === "object" ? { ...payload.relist_usage_by_date } : {};
					const todayCount = Number(relistCounts[todayKey]);
					relistCounts[todayKey] = (Number.isFinite(todayCount) && todayCount > 0 ? todayCount : 0) + 1;
					const { error } = await client
						.from("property_listings")
						.update({
							updated_at: nowIso,
							payload: { ...payload, relist_usage_by_date: relistCounts, last_relisted_at: nowIso }
						})
						.eq("id", rowId)
						.eq("user_id", user.id);
					if (error) throw error;
					successCount += 1;
				}

				clearBrokerListingRowsCache();
				await loadBrokerListings({ force: true });
				if (typeof window.realjejuReloadMapListings === "function") window.realjejuReloadMapListings();
				const suffix = candidates.length > refreshRows.length ? ` 하루 한도 ${dailyLimit}건 안에서 ${successCount}건만 갱신했습니다.` : "";
				openAuthErrorModal(`${successCount}건을 현재시간으로 갱신했습니다.${suffix}`, "전체갱신", null);
			}
			catch (err) {
				console.error("중개사 홈 전체갱신 실패:", err);
				openAuthErrorModal("전체갱신 처리에 실패했습니다.", "전체갱신", null);
			}
			finally {
				window.realjejuBrokerBulkRefreshBusy = false;
				if (button) button.disabled = false;
			}
		}

	function confirmBrokerListingDelete(listingId)
	{
		openAuthConfirmModal("선택한 매물을 휴지통으로 이동할까요?", "매물 삭제", () => {
			updateBrokerListingRowAction(listingId, "delete");
		}, null);
	}

	function confirmBrokerListingPermanentDelete(listingId)
	{
		openAuthConfirmModal("휴지통 매물을 영구 삭제할까요?", "영구 삭제", () => {
			updateBrokerListingRowAction(listingId, "permanent_delete");
		}, null);
	}

	// 중개사 홈 필터는 부동산 홈처럼 섹션형 타일 드롭다운으로 관리한다
	const BROKER_HOME_DEFAULT_DEAL_FILTER_VALUES = ["sale", "jeonse", "monthly", "yearly"];

	function createBrokerHomeDefaultDealFilterSet()
	{
		return new Set(BROKER_HOME_DEFAULT_DEAL_FILTER_VALUES);
	}

	function isBrokerHomeDefaultDealFilter(values)
	{
		if (!(values instanceof Set)) return false;
		return BROKER_HOME_DEFAULT_DEAL_FILTER_VALUES.every((value) => values.has(value))
			&& Array.from(values).every((value) => BROKER_HOME_DEFAULT_DEAL_FILTER_VALUES.includes(value));
	}

	function getBrokerHomeFilters()
	{
		if (!window.realjejuBrokerHomeFilters) {
			window.realjejuBrokerHomeFilters = {
				status: "all",
				property: new Set(),
				deal: createBrokerHomeDefaultDealFilterSet(),
				area: new Set(),
				areaRange: { min: 0, max: AREA_FILTER_MAX_M2, exclusive: true, land: false, unit: "m2" },
				landType: new Set(),
				landUseZone: new Set()
			};
		}
		["property", "deal", "area", "landType", "landUseZone"].forEach((key) => {
			if (!(window.realjejuBrokerHomeFilters[key] instanceof Set)) {
				window.realjejuBrokerHomeFilters[key] = new Set(window.realjejuBrokerHomeFilters[key] ? [window.realjejuBrokerHomeFilters[key]] : []);
			}
		});
		if (!window.realjejuBrokerHomeFilters.areaRange || typeof window.realjejuBrokerHomeFilters.areaRange !== "object") {
			window.realjejuBrokerHomeFilters.areaRange = { min: 0, max: AREA_FILTER_MAX_M2, exclusive: true, land: false, unit: "m2" };
		}
		if (window.realjejuBrokerHomeFilters.deal instanceof Set) window.realjejuBrokerHomeFilters.deal.delete("short");
		return window.realjejuBrokerHomeFilters;
	}

	function syncBrokerHomeFilterArrow(type, isOpen)
	{
		const btn = document.getElementById(getBrokerHomeFilterBtnId(type));
		const icon = btn ? btn.querySelector("i.fa-solid") : null;
		if (!icon) return;
		icon.classList.toggle("fa-chevron-up", !!isOpen);
		icon.classList.toggle("fa-chevron-down", !isOpen);
	}

	function syncBrokerHomeFilterArrows()
	{
		["property", "deal", "area", "landType", "landUseZone"].forEach((type) => {
			const menu = document.getElementById(getBrokerHomeFilterMenuId(type));
			syncBrokerHomeFilterArrow(type, !!(menu && menu.classList.contains("open")));
		});
	}

	const brokerHomeFilterMenuMedia = window.matchMedia("(max-width: 850px)");
	const brokerHomeFilterMenuOrigins = new WeakMap();
	const brokerHomeFilterMenuSelector = "#brokerPropertyTypeFilterMenu, #brokerPriceTypeFilterMenu, #brokerAreaFilterMenu, #brokerLandTypeFilterMenu, #brokerLandUseZoneFilterMenu, [data-favorite-filter-panel]";

	function restoreBrokerHomeFilterMenuOrigin(menu)
	{
		if (!menu) return;
		menu.classList.remove("broker-home-filter-menu-mobile-centered");
		const origin = brokerHomeFilterMenuOrigins.get(menu);
		if (!origin || !origin.parent || menu.parentNode === origin.parent) return;
		const anchor = origin.nextSibling && origin.nextSibling.parentNode === origin.parent ? origin.nextSibling : null;
		origin.parent.insertBefore(menu, anchor);
	}

	function mountBrokerHomeFilterMenuForViewport(menu)
	{
		if (!menu || !menu.matches(brokerHomeFilterMenuSelector)) return;
		const menuPageOpen = menu.matches("[data-favorite-filter-panel]")
			? document.body.classList.contains("my-suite-page-open")
			: document.body.classList.contains("broker-home-page-open");
		if (!brokerHomeFilterMenuMedia.matches || !menuPageOpen) {
			restoreBrokerHomeFilterMenuOrigin(menu);
			return;
		}
		if (!brokerHomeFilterMenuOrigins.has(menu) && menu.parentNode) {
			brokerHomeFilterMenuOrigins.set(menu, { parent: menu.parentNode, nextSibling: menu.nextSibling });
		}
		if (menu.parentNode !== document.body) document.body.appendChild(menu);
		menu.classList.add("broker-home-filter-menu-mobile-centered");
	}

	function syncOpenBrokerHomeFilterMenusForViewport()
	{
		document.querySelectorAll(brokerHomeFilterMenuSelector).forEach((menu) => {
			if (menu.classList.contains("open")) mountBrokerHomeFilterMenuForViewport(menu);
			else restoreBrokerHomeFilterMenuOrigin(menu);
		});
	}

	if (typeof brokerHomeFilterMenuMedia.addEventListener === "function") {
		brokerHomeFilterMenuMedia.addEventListener("change", syncOpenBrokerHomeFilterMenusForViewport);
	} else if (typeof brokerHomeFilterMenuMedia.addListener === "function") {
		brokerHomeFilterMenuMedia.addListener(syncOpenBrokerHomeFilterMenusForViewport);
	}

	window.realjejuSyncOpenManagementFilterMenusForViewport = syncOpenBrokerHomeFilterMenusForViewport;
	window.realjejuRestoreManagementFilterMenuOrigin = restoreBrokerHomeFilterMenuOrigin;

	function closeBrokerHomeFilterMenus(exceptType)
	{
		document.querySelectorAll(".broker-home-filter-menu.open").forEach((menu) => {
			const normalizedMenuId = menu.id.toLowerCase().replace(/[^a-z0-9]/g, "");
			const normalizedExcept = String(exceptType || "").toLowerCase().replace(/[^a-z0-9]/g, "");
			if (!exceptType || !normalizedMenuId.includes(normalizedExcept)) {
				menu.classList.remove("open");
			restoreBrokerHomeFilterMenuOrigin(menu);
			}
		});
		syncBrokerHomeFilterArrows();
	}

